import { describe, expect, it } from "vitest";
import { levenshtein, namesMatch } from "./fuzzyMatch";

describe("levenshtein", () => {
  it("is 0 for identical strings", () => {
    expect(levenshtein("abc", "abc")).toBe(0);
  });

  it("counts a single substitution", () => {
    expect(levenshtein("vyčerpaný", "vyčerpaní")).toBe(1);
  });

  it("handles empty strings", () => {
    expect(levenshtein("", "abc")).toBe(3);
    expect(levenshtein("abc", "")).toBe(3);
  });
});

describe("namesMatch", () => {
  it("matches identical names", () => {
    expect(namesMatch("Popálená ruka", "popálená ruka")).toBe(true);
  });

  it("matches Czech word-form variants (adjective vs noun)", () => {
    expect(namesMatch("vyčerpaný", "vyčerpání")).toBe(true);
  });

  it("does not merge different body parts", () => {
    expect(namesMatch("zraněná ruka", "zraněná noha")).toBe(false);
  });

  it("does not merge unrelated conditions", () => {
    expect(namesMatch("otřesený", "unavený")).toBe(false);
  });

  it("does not merge different word counts", () => {
    expect(namesMatch("popálená ruka", "popálená pravá ruka")).toBe(false);
  });

  it("does not fuzz very short words", () => {
    expect(namesMatch("bg", "bd")).toBe(false);
  });
});

import { describe, expect, it } from "vitest";

import {
  findAddressedMember,
  mergeConsecutiveRoles,
  pickNextSpeaker,
  stripSpeakerPrefix,
  type SpeakerCandidate,
} from "./groupSpeaker";
import type { PromptMessage } from "../prompt/promptBuilder";

const MEMBERS: SpeakerCandidate[] = [
  { id: "a", name: "Anna", position: 0 },
  { id: "b", name: "Věž", position: 1 },
  { id: "c", name: "Kai", position: 2 },
];

describe("pickNextSpeaker", () => {
  it("returns null for an empty member list", () => {
    expect(pickNextSpeaker([], "hello", [])).toBeNull();
  });

  it("returns the only member for a single-member list, ignoring text/history", () => {
    const single: SpeakerCandidate[] = [{ id: "a", name: "Anna", position: 0 }];
    expect(pickNextSpeaker(single, "", [])).toBe("a");
  });

  it("matches a name mentioned without diacritics ('vez' -> 'Věž')", () => {
    expect(pickNextSpeaker(MEMBERS, "rekni to vez", [])).toBe("b");
  });

  it("picks the last-mentioned member when several are named in the text", () => {
    const text = "Anna a Kai si povidali, pak prisla Vez.";
    expect(pickNextSpeaker(MEMBERS, text, [])).toBe("b");
  });

  it("falls back to round-robin on the longest-silent member when no name is mentioned", () => {
    // a and b have spoken recently (oldest -> newest); c never spoke.
    const recent = ["a", "b", "a"];
    expect(pickNextSpeaker(MEMBERS, "no names here", recent)).toBe("c");
  });

  it("prefers never-spoken members by position when several never spoke", () => {
    const recent = ["a"]; // b and c never spoke; b has lower position
    expect(pickNextSpeaker(MEMBERS, "", recent)).toBe("b");
  });

  it("picks the member who spoke longest ago when everyone has spoken", () => {
    const recent = ["c", "a", "b", "a"]; // last occurrence indices: c=0, a=3, b=2
    expect(pickNextSpeaker(MEMBERS, "", recent)).toBe("c");
  });

  it("handles empty text by falling back to round-robin", () => {
    expect(pickNextSpeaker(MEMBERS, "", [])).toBe("a");
  });

  it("picks the member addressed by name in the last assistant text when user text has no mention", () => {
    // Assistant said "Kai se na tebe podívá" — Kai is mentioned.
    expect(pickNextSpeaker(MEMBERS, "co bude dál?", ["a", "b"], "Kai se na tebe podívá")).toBe("c");
  });

  it("ignores assistant text when user already mentioned a name (user priority)", () => {
    // Even though assistant mentioned Kai, user mentioned Anna last.
    // Use bare nominative so foldForSearch("Anna") = "anna" is a substring.
    expect(
      pickNextSpeaker(MEMBERS, "řekni to Anna", ["a", "c"], "Kai přikývl."),
    ).toBe("a");
  });

  it("falls back to LRS when assistant text has no member name", () => {
    expect(
      pickNextSpeaker(MEMBERS, "nic", ["a", "b"], "Jen ticho."),
    ).toBe("c"); // c never spoke
  });

  it("is backward-compatible when lastAssistantText is omitted", () => {
    expect(pickNextSpeaker(MEMBERS, "no names here", ["a", "b", "a"])).toBe("c");
  });
});

describe("findAddressedMember", () => {
  it("returns null for empty text", () => {
    expect(findAddressedMember("", MEMBERS)).toBeNull();
  });

  it("returns null for empty member list", () => {
    expect(findAddressedMember("Anna se směje.", [])).toBeNull();
  });

  it("returns the last-mentioned member in the assistant text", () => {
    // "Anna" appears first, "Kai" appears last.
    expect(findAddressedMember("Anna se podívala na Kaie.", MEMBERS)).toBe("c");
  });

  it("is fold/diacritics insensitive", () => {
    expect(findAddressedMember("vez se usmála.", MEMBERS)).toBe("b");
  });

  it("returns null when no member is mentioned", () => {
    expect(findAddressedMember("Nikdo tu není.", MEMBERS)).toBeNull();
  });

  it("finds a name near a Czech addressing pronoun (coreference)", () => {
    // "mu" is the pronoun, "Kai" appears before it (inside "Kaie").
    expect(
      findAddressedMember("Podíval se na Kaie a řekl mu tajemství.", MEMBERS),
    ).toBe("c");
  });

  it("picks the closest name before the pronoun when several appear", () => {
    // "Kai" appears closer to "ti" than "Anna".
    expect(
      findAddressedMember("Anna vešla. Kai ti něco pošeptal.", MEMBERS),
    ).toBe("c");
  });
});

describe("stripSpeakerPrefix", () => {
  it("strips a plain 'Name:' prefix", () => {
    expect(stripSpeakerPrefix("Anna: Hello there.", "Anna")).toBe("Hello there.");
  });

  it("strips a bold '**Name:**' prefix", () => {
    expect(stripSpeakerPrefix("**Anna:** Hello there.", "Anna")).toBe("Hello there.");
  });

  it("is case/diacritics insensitive when matching the prefix", () => {
    expect(stripSpeakerPrefix("VEZ: Ahoj.", "Věž")).toBe("Ahoj.");
  });

  it("does not touch an occurrence of the name in the middle of the text", () => {
    const text = "He said hello, Anna: that was odd.";
    expect(stripSpeakerPrefix(text, "Anna")).toBe(text);
  });

  it("is a no-op when the prefix belongs to a different name", () => {
    const text = "Kai: Hello there.";
    expect(stripSpeakerPrefix(text, "Anna")).toBe(text);
  });

  it("is a no-op on text with no prefix at all", () => {
    const text = "Just a plain sentence.";
    expect(stripSpeakerPrefix(text, "Anna")).toBe(text);
  });
});

describe("mergeConsecutiveRoles", () => {
  it("merges adjacent same-role messages by joining content with \\n\\n", () => {
    const input: PromptMessage[] = [
      { role: "system", content: "sys" },
      { role: "assistant", content: "Anna: Hi." },
      { role: "assistant", content: "Kai: Yo." },
      { role: "user", content: "Hey both." },
    ];
    expect(mergeConsecutiveRoles(input)).toEqual([
      { role: "system", content: "sys" },
      { role: "assistant", content: "Anna: Hi.\n\nKai: Yo." },
      { role: "user", content: "Hey both." },
    ]);
  });

  it("leaves already-alternating messages untouched", () => {
    const input: PromptMessage[] = [
      { role: "user", content: "u1" },
      { role: "assistant", content: "a1" },
      { role: "user", content: "u2" },
    ];
    expect(mergeConsecutiveRoles(input)).toEqual(input);
  });

  it("handles an empty list", () => {
    expect(mergeConsecutiveRoles([])).toEqual([]);
  });

  it("does not mutate the input array's message objects", () => {
    const input: PromptMessage[] = [
      { role: "assistant", content: "a1" },
      { role: "assistant", content: "a2" },
    ];
    const out = mergeConsecutiveRoles(input);
    expect(input[0].content).toBe("a1");
    expect(out[0].content).toBe("a1\n\na2");
  });
});

import { describe, expect, it } from "vitest";

import {
  buildPromotionPrompt,
  parsePromotedCard,
  truncateTranscript,
  type TranscriptEntry,
} from "./npcPromotion";

describe("parsePromotedCard", () => {
  it("parses a plain JSON object", () => {
    const raw =
      '{"name":"Elarion","description":"A wandering scout.","personality":"Cautious.","scenario":"Meets the party at the crossroads.","first_mes":""}';
    expect(parsePromotedCard(raw)).toEqual({
      name: "Elarion",
      description: "A wandering scout.",
      personality: "Cautious.",
      scenario: "Meets the party at the crossroads.",
      firstMes: "",
    });
  });

  it("strips ```json code fences", () => {
    const raw =
      '```json\n{"name":"Elarion","description":"Scout.","personality":"Cautious.","scenario":"Crossroads.","first_mes":""}\n```';
    expect(parsePromotedCard(raw)).toMatchObject({ name: "Elarion" });
  });

  it("strips plain ``` fences without a language tag", () => {
    const raw =
      '```\n{"name":"Elarion","description":"Scout.","personality":"Cautious.","scenario":"Crossroads.","first_mes":""}\n```';
    expect(parsePromotedCard(raw)).toMatchObject({ name: "Elarion" });
  });

  it("finds the object even with leading/trailing prose", () => {
    const raw =
      'Here is the card:\n{"name":"Elarion","description":"Scout.","personality":"Cautious.","scenario":"Crossroads.","first_mes":""}\nLet me know if you need changes.';
    expect(parsePromotedCard(raw)).toMatchObject({ name: "Elarion" });
  });

  it("always forces firstMes to empty even if the model filled it in", () => {
    const raw =
      '{"name":"Elarion","description":"Scout.","personality":"Cautious.","scenario":"Crossroads.","first_mes":"Hello there!"}';
    expect(parsePromotedCard(raw)?.firstMes).toBe("");
  });

  it("returns null for unparseable input instead of throwing", () => {
    expect(parsePromotedCard("not json at all")).toBeNull();
    expect(parsePromotedCard("")).toBeNull();
    expect(parsePromotedCard("{broken json")).toBeNull();
  });

  it("returns null when a required field is missing", () => {
    const raw = '{"name":"Elarion","description":"Scout.","scenario":"Crossroads.","first_mes":""}';
    expect(parsePromotedCard(raw)).toBeNull();
  });

  it("returns null when there's no object at all", () => {
    expect(parsePromotedCard('["name","Elarion"]')).toBeNull();
  });
});

describe("truncateTranscript", () => {
  function msg(i: number): TranscriptEntry {
    return { role: "assistant", content: `message ${i}` };
  }

  it("keeps only the last `max` messages, oldest first", () => {
    const messages = Array.from({ length: 50 }, (_, i) => msg(i));
    const result = truncateTranscript(messages, 40);
    expect(result).toHaveLength(40);
    expect(result[0].content).toBe("message 10");
    expect(result[39].content).toBe("message 49");
  });

  it("returns everything when there are fewer than `max` messages", () => {
    const messages = [msg(0), msg(1)];
    expect(truncateTranscript(messages, 40)).toHaveLength(2);
  });

  it("truncates overly long message content", () => {
    const long = "x".repeat(1000);
    const [result] = truncateTranscript([{ role: "user", content: long }], 40);
    expect(result.content.length).toBeLessThan(1000);
    expect(result.content.endsWith("…")).toBe(true);
  });
});

describe("buildPromotionPrompt", () => {
  it("includes the NPC name, facts, and transcript in the user message", () => {
    const messages = buildPromotionPrompt(
      "Elarion",
      [{ subject: "Elarion", fact: "A scout who knows the forest paths." }],
      [{ role: "user", content: "Elarion waves at us." }],
    );
    expect(messages[0].role).toBe("system");
    expect(messages[1].role).toBe("user");
    expect(messages[1].content).toContain("Elarion");
    expect(messages[1].content).toContain("A scout who knows the forest paths.");
    expect(messages[1].content).toContain("Elarion waves at us.");
  });

  it("caps the transcript included in the prompt to MAX_CONTEXT_MESSAGES", () => {
    const many = Array.from({ length: 100 }, (_, i) => ({
      role: "assistant" as const,
      content: `line ${i}`,
    }));
    const messages = buildPromotionPrompt("NPC", [], many);
    expect(messages[1].content).not.toContain("line 0\n");
    expect(messages[1].content).toContain("line 99");
  });
});

// Chat log — records every prompt sent to the AI and every response
// received into per-chat files (`chat-{chatId}.log`) in the same
// `$APPDATA/logs/` directory as `app.log`. When a chat is deleted its
// log file is deleted too. The user can inspect what the model actually
// saw vs what it returned directly from the Diagnostics panel.
//
// Fire-and-forget: a failed write never surfaces to the user — same
// reliability posture as the error logger (`src/logging.ts`).

import { invoke } from "@tauri-apps/api/core";
import type { ChatMessage } from "../providers/types";

const MAX_SECTION_CHARS = 16_000; // per section (prompt / response), before the 32KB Rust cap

/** Formats `apiMessages` (the exact array sent to the model) into a
 *  human-readable text block. System/user/assistant roles are labeled;
 *  tool calls and function responses are included but collapsed to one
 *  line each to keep the prompt block compact. */
function formatPrompt(apiMessages: ChatMessage[]): string {
  const lines: string[] = [];
  for (const msg of apiMessages) {
    const role = msg.role;
    const content = msg.content ?? "";

    if (msg.function_call) {
      lines.push(
        `[assistant → function_call ${msg.function_call.name}(${JSON.stringify(msg.function_call.args)})]`,
      );
      continue;
    }
    if (msg.function_response) {
      const resp = msg.function_response.response;
      const summary =
        typeof resp === "object" && resp !== null && "result" in resp
          ? String((resp as { result: unknown }).result).slice(0, 120)
          : JSON.stringify(resp).slice(0, 120);
      lines.push(`[function_response ${msg.function_response.name}: ${summary}]`);
      continue;
    }

    const label = role === "system" ? "SYSTEM" : role === "assistant" ? "ASSISTANT" : "USER";
    const body = content.slice(0, MAX_SECTION_CHARS);
    lines.push(`--- ${label} ---\n${body}`);
  }
  return lines.join("\n").slice(0, MAX_SECTION_CHARS);
}

/** Formats a single prompt+response exchange into one log block. Each
 *  block is delimited by `══════` lines so the viewer can jump between
 *  exchanges visually. The frontend calls `invoke("append_chat_log")`
 *  with the full block — the Rust side handles rotation + truncation. */
export function logChatExchange(
  connectionName: string,
  modelName: string,
  chatId: string | null | undefined,
  apiMessages: ChatMessage[],
  responseText: string,
) {
  const ts = new Date().toISOString();
  const conn = `${connectionName}/${modelName}`;
  const chatTag = chatId ? ` chat=${chatId}` : "";
  const promptBlock = formatPrompt(apiMessages);
  const respBlock = responseText.slice(0, MAX_SECTION_CHARS);

  const block = [
    `══════ PROMPT ${ts} ${conn}${chatTag} ══════`,
    promptBlock,
    `══════ RESPONSE ${ts} ${conn}${chatTag} (${responseText.length} chars) ══════`,
    respBlock,
    "", // trailing newline so the next exchange starts on a fresh line
  ].join("\n");

  if (!chatId) return; // per-chat file requires a chat ID
  void invoke("append_chat_log", { chatId, line: block }).catch(() => {});
}

use std::fs;
use std::io::Write;
use std::path::PathBuf;

use tauri::{AppHandle, Manager};

use crate::commands::secrets::get_api_key;
use crate::providers::{self, ChatMessage, ConnectionDto, Role};

const EXTRACTION_SYSTEM_PROMPT: &str = r#"You are a game state extractor for an RPG. Read the narrator's response below and extract any game-mechanical changes into a single JSON object.

Return ONLY the JSON object, no other text, no markdown fences. The JSON must use this schema:

{
  "time_elapsed_minutes": number | null,
  "inventory": [{"op": "add" | "remove", "item": "string", "qty": number}],
  "skills": [{"name": "string", "delta": number}],
  "levels": {"xp_delta": number, "level_delta": number},
  "conditions": [{"op": "add" | "remove", "name": "string", "description": "string | null", "duration": "string | null"}],
  "modifications": [{"op": "add" | "remove", "name": "string"}],
  "factions": [{"name": "string", "delta": number}],
  "crafting": [{"result_item": "string", "ingredients": ["string"]}],
  "crafted": [{"result_item": "string", "perks": ["string"]}],
  "quests": [{"op": "start" | "complete" | "fail" | "note", "name": "string", "note": "string | null"}],
  "game_over": "string | null",
  "check_skill": "string | null",
  "relevant_context": {
    "skills": ["string"],
    "item_keywords": ["string"],
    "recipe_keywords": ["string"]
  }
}

Rules:
- If nothing changed in a category, use an empty array or null.
- time_elapsed_minutes: how many minutes passed in the story (e.g. "two hours later" = 120). If unclear, use null.
- inventory: items gained, lost, or whose qty changed. "He found a sword" = add sword qty 1. "He dropped his shield" = remove shield qty 1.
- skills: new skills learned or existing ones improved. Delta is the change (positive = improved, negative = worsened).
- levels: xp_delta is XP change, level_delta is level change.
- conditions: temporary effects like "exhausted", "injured", "blessed".
- modifications: permanent body changes like "scar on cheek", "tattoo".
- factions: reputation changes with named groups.
- crafting: new recipes discovered (result_item + ingredients).
- crafted: items successfully crafted (result_item + perks).
- quests: new quests started, completed, failed, or noted.
- game_over: if the character died, state the reason. Otherwise null.
- check_skill: if a skill check was called, name the skill. Otherwise null.
- relevant_context: helps filter what skills/items/recipes to show the storyteller in the next turn. Look at the current scene and list:
  - skills: name any character skills the scene suggests could be useful (e.g. a river suggests Swimming, a locked door suggests Lockpicking). Include skills that ARE ALREADY KNOWN by the character. Empty array if no skills stand out.
  - item_keywords: keywords from the scene that suggest what items might be needed (e.g. "river" → "voda", "rope", "boat"). These help surface relevant inventory items.
  - recipe_keywords: keywords from materials or crafting opportunities in the scene (e.g. "iron ore" → "železo", "ruda"). These help surface relevant crafting recipes.

IMPORTANT: Only extract changes that are explicitly described in the text. Do not invent or hallucinate. If the text just describes scenery or dialogue with no mechanical changes, return empty arrays."#;

fn extractor_log_path(app: &AppHandle) -> Result<PathBuf, String> {
    let dir = app
        .path()
        .app_data_dir()
        .map_err(|e| format!("nepodařilo se najít adresář aplikace: {e}"))?
        .join("logs");
    fs::create_dir_all(&dir).map_err(|e| format!("nepodařilo se vytvořit adresář logů: {e}"))?;
    Ok(dir.join("extractor.log"))
}

fn append_extractor_log(app: &AppHandle, line: &str) {
    let Ok(path) = extractor_log_path(app) else { return };
    let mut file = match fs::OpenOptions::new().create(true).append(true).open(&path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let _ = writeln!(file, "{line}");
}

fn chrono_now() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = dur.as_secs();
    let millis = dur.subsec_millis();
    let days_since_epoch = secs / 86400;
    let time_of_day = secs % 86400;
    let hours = time_of_day / 3600;
    let minutes = (time_of_day % 3600) / 60;
    let secs_rem = time_of_day % 60;
    let total_days = days_since_epoch as i64;
    let z = total_days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u32;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if m <= 2 { y + 1 } else { y };
    format!("{year:04}-{m:02}-{d:02}T{hours:02}:{minutes:02}:{secs_rem:02}.{millis:03}Z")
}

/// Sends the narrator's response to a tag-extraction model (typically a
/// fast/free model like Gemini Flash) and returns the model's JSON output.
/// Also writes a detailed debug log to `extractor.log` in the app data
/// directory so the user can inspect extraction I/O in real time.
#[tauri::command]
pub async fn extract_game_tags(
    app: AppHandle,
    connection: ConnectionDto,
    response_text: String,
    state_context: Option<String>,
) -> Result<String, String> {
    let ts = chrono_now();

    // Build the user message: state context (if any) + narrator response.
    let user_message = match state_context {
        Some(ref ctx) if !ctx.is_empty() => format!("{ctx}\n\n---\n\n{response_text}"),
        _ => response_text.clone(),
    };

    // Log input (truncated)
    let input_preview: String = response_text.chars().take(500).collect();
    append_extractor_log(
        &app,
        &format!(
            "══════ EXTRACT {ts} IN ({}/{}) ══════\n{input_preview}…",
            connection.provider, connection.model
        ),
    );

    let api_key = get_api_key(&connection.id)
        .map_err(|e| e.to_string())?
        .ok_or_else(|| "Pro toto připojení není uložen žádný API klíč.".to_string())?;

    let messages = vec![
        ChatMessage {
            role: Role::System,
            content: EXTRACTION_SYSTEM_PROMPT.into(),
            function_call: None,
            function_response: None,
        },
        ChatMessage {
            role: Role::User,
            content: user_message,
            function_call: None,
            function_response: None,
        },
    ];

    let raw = providers::complete(&connection, &api_key, &messages)
        .await
        .map_err(|e| {
            append_extractor_log(&app, &format!("ERROR: {e}"));
            e.to_string()
        })?;

    // Log output (truncated)
    let output_preview: String = raw.chars().take(800).collect();
    append_extractor_log(
        &app,
        &format!("══════ RESULT {ts} ══════\n{output_preview}"),
    );

    // Strip markdown fences
    let trimmed = raw.trim();
    if trimmed.starts_with("```") {
        let inner = trimmed
            .strip_prefix("```json")
            .or_else(|| trimmed.strip_prefix("```"))
            .unwrap_or(trimmed);
        let cleaned = inner.strip_suffix("```").unwrap_or(inner);
        Ok(cleaned.trim().to_string())
    } else {
        Ok(trimmed.to_string())
    }
}

import { useState, useMemo } from "react";
import { useTranslation } from "react-i18next";
import type { SkillEntry } from "../../db/repositories/personasRepo";

interface CraftingRecipe {
  resultItem: string;
  ingredients: string[];
  skillName?: string | null;
  perks: string[];
  craftedAt?: string | null;
}

interface Props {
  skills: SkillEntry[];
  inventory: { item: string; qty: number }[];
  recipes: CraftingRecipe[];
  /** Called when the user clicks a skill/recipe reference — the caller
   *  should pass this text to ChatInput's `insertRef` prop or the
   *  `__mstInsertPrompt` global. */
  onInsert: (text: string) => void;
}

type Tab = "skills" | "recipes";

export function ReferencePanel({ skills, inventory, recipes, onInsert }: Props) {
  const { t } = useTranslation("chat");
  const [tab, setTab] = useState<Tab>("skills");
  const [search, setSearch] = useState("");

  const filteredSkills = useMemo(() => {
    if (!search) return skills;
    const q = search.toLowerCase();
    return skills.filter((s) => s.name.toLowerCase().includes(q));
  }, [skills, search]);

  const filteredRecipes = useMemo(() => {
    const inventoryNames = new Set(inventory.map((i) => i.item.toLowerCase()));
    // Score recipes: those with available ingredients first, then by name
    const scored = recipes.map((r) => {
      const hasAll = r.ingredients.every((ing) => inventoryNames.has(ing.toLowerCase()));
      const hasSome = r.ingredients.some((ing) => inventoryNames.has(ing.toLowerCase()));
      return { ...r, hasAll, hasSome };
    });
    if (!search) {
      scored.sort((a, b) => {
        if (a.hasAll !== b.hasAll) return a.hasAll ? -1 : 1;
        if (a.hasSome !== b.hasSome) return a.hasSome ? -1 : 1;
        return a.resultItem.localeCompare(b.resultItem);
      });
      return scored;
    }
    const q = search.toLowerCase();
    return scored
      .filter((r) => r.resultItem.toLowerCase().includes(q)
        || r.ingredients.some((ing) => ing.toLowerCase().includes(q)))
      .sort((a, b) => {
        if (a.hasAll !== b.hasAll) return a.hasAll ? -1 : 1;
        if (a.hasSome !== b.hasSome) return a.hasSome ? -1 : 1;
        return a.resultItem.localeCompare(b.resultItem);
      });
  }, [recipes, inventory, search]);

  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center gap-1 border-b p-2" style={{ borderColor: "var(--color-border)" }}>
        {(["skills", "recipes"] as Tab[]).map((tabName) => (
          <button
            key={tabName}
            type="button"
            onClick={() => setTab(tabName)}
            className="rounded-[var(--radius-sm)] px-3 py-1 text-xs font-medium transition-colors"
            style={{
              backgroundColor: tab === tabName ? "var(--color-accent)" : "transparent",
              color: tab === tabName ? "var(--color-accent-contrast, #fff)" : "var(--color-text-muted)",
            }}
          >
            {tabName === "skills" ? t("room.skillsTitle", "Skills") : t("room.recipesTitle", "Recipes")}
          </button>
        ))}
        <div className="flex-1" />
        <input
          type="text"
          placeholder={tab === "skills" ? "🔍 skill…" : "🔍 recept…"}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="rounded-[var(--radius-sm)] border px-2 py-1 text-xs"
          style={{
            borderColor: "var(--color-border)",
            backgroundColor: "var(--color-surface-2)",
            color: "var(--color-text)",
            width: "120px",
          }}
        />
      </div>

      <div className="flex-1 overflow-y-auto p-2">
        {tab === "skills" && (
          filteredSkills.length === 0 ? (
            <p className="text-xs" style={{ color: "var(--color-text-muted)" }}>
              {t("room.skillsEmpty", "No skills yet.")}
            </p>
          ) : (
            <div className="flex flex-col gap-1">
              {filteredSkills.map((s) => (
                <button
                  key={s.name}
                  type="button"
                  onClick={() => onInsert(`@${s.name}`)}
                  className="flex items-center gap-2 rounded-[var(--radius-sm)] px-2 py-1.5 text-left text-xs transition-colors hover:opacity-80"
                  style={{ backgroundColor: "var(--color-surface-2)", color: "var(--color-text)" }}
                >
                  <span className="font-medium">{s.name}</span>
                  <span style={{ color: "var(--color-accent)" }}>{s.level}</span>
                </button>
              ))}
            </div>
          )
        )}

        {tab === "recipes" && (
          filteredRecipes.length === 0 ? (
            <p className="text-xs" style={{ color: "var(--color-text-muted)" }}>
              {t("room.recipesEmpty", "No recipes yet.")}
            </p>
          ) : (
            <div className="flex flex-col gap-1">
              {filteredRecipes.map((r) => (
                <button
                  key={r.resultItem}
                  type="button"
                  onClick={() => onInsert(`@craft ${r.resultItem}`)}
                  className="flex flex-col gap-0.5 rounded-[var(--radius-sm)] px-2 py-1.5 text-left text-xs transition-colors hover:opacity-80"
                  style={{
                    backgroundColor: r.hasAll ? "var(--color-success-subtle, rgba(34,197,94,0.12))"
                      : r.hasSome ? "var(--color-surface-2)"
                      : "var(--color-surface-2)",
                    color: "var(--color-text)",
                  }}
                >
                  <div className="flex items-center gap-2">
                    <span>{r.craftedAt ? "✓" : "✗"}</span>
                    <span className="font-medium">{r.resultItem}</span>
                  </div>
                  <div className="flex flex-wrap gap-1" style={{ color: "var(--color-text-muted)" }}>
                    {r.ingredients.map((ing) => {
                      const has = inventory.some((i) => i.item.toLowerCase() === ing.toLowerCase());
                      return (
                        <span
                          key={ing}
                          style={{ color: has ? "var(--color-success)" : "var(--color-text-faint)" }}
                        >
                          {ing}
                        </span>
                      );
                    })}
                  </div>
                  {r.skillName && (
                    <span style={{ color: "var(--color-text-faint)" }}>skill: {r.skillName}</span>
                  )}
                </button>
              ))}
            </div>
          )
        )}
      </div>
    </div>
  );
}

import { describe, expect, it } from "vitest";

import { parseGameTags } from "./inventoryTags";

describe("parseGameTags — quest tags", () => {
  it("parses documented start/complete/fail forms", () => {
    expect(parseGameTags("[QUEST:+Najít klíč]").questMutations).toEqual([
      { op: "start", name: "Najít klíč", note: undefined },
    ]);
    expect(parseGameTags("[QUEST:✓Najít klíč]").questMutations).toEqual([
      { op: "complete", name: "Najít klíč", note: undefined },
    ]);
    expect(parseGameTags("[QUEST:-Najít klíč]").questMutations).toEqual([
      { op: "fail", name: "Najít klíč", note: undefined },
    ]);
  });

  it("parses the loose model output with a status suffix", () => {
    const { questMutations, cleanText } = parseGameTags(
      "Text před. [QUEST: Hledání prastarých runových fragmentů (aktivní)] Text po.",
    );
    expect(questMutations).toEqual([
      { op: "start", name: "Hledání prastarých runových fragmentů", note: undefined },
    ]);
    expect(cleanText).not.toContain("[QUEST");
  });

  it("maps completion suffixes and notes", () => {
    expect(parseGameTags("[QUEST: Runy (splněno)]").questMutations[0].op).toBe("complete");
    expect(parseGameTags("[QUEST:Runy: našel jsi první fragment]").questMutations[0]).toEqual({
      op: "note",
      name: "Runy",
      note: "našel jsi první fragment",
    });
  });

  it("strips quest tags from the visible text", () => {
    const { cleanText } = parseGameTags("Jdeš dál. [QUEST:+Cesta na sever]");
    expect(cleanText.trim()).toBe("Jdeš dál.");
  });
});

describe("parseGameTags — condition tags", () => {
  it("parses add with optional duration and remove", () => {
    expect(parseGameTags("[COND:+Otrava:3 dny]").conditionMutations).toEqual([
      { op: "add", name: "Otrava", duration: "3 dny" },
    ]);
    expect(parseGameTags("[COND:-Otrava]").conditionMutations).toEqual([
      { op: "remove", name: "Otrava", duration: undefined },
    ]);
  });
});

describe("parseGameTags — body modification tags", () => {
  it("parses add and remove", () => {
    expect(parseGameTags("[MOD:+Jizva přes tvář]").modMutations).toEqual([
      { op: "add", name: "Jizva přes tvář" },
    ]);
    expect(parseGameTags("[MOD:-Jizva přes tvář]").modMutations).toEqual([
      { op: "remove", name: "Jizva přes tvář" },
    ]);
  });

  it("strips modification tags from the visible text", () => {
    const { cleanText } = parseGameTags("Rána se zahojila do jizvy. [MOD:+Jizva na paži]");
    expect(cleanText.trim()).toBe("Rána se zahojila do jizvy.");
  });
});

describe("parseGameTags — skill tags", () => {
  it("parses the documented +/- forms", () => {
    expect(parseGameTags("[SKILL:+Pěst]").skillChanges).toEqual([
      { name: "Pěst", delta: 1, absolute: null },
    ]);
    expect(parseGameTags("[SKILL:Pěst+2]").skillChanges).toEqual([
      { name: "Pěst", delta: 2, absolute: null },
    ]);
  });

  it("parses the loose progress format the model actually emits", () => {
    const { skillChanges, cleanText } = parseGameTags(
      "Text. [SKILL: Rozebírání artefaktů 3/10] Text.",
    );
    expect(skillChanges).toEqual([{ name: "Rozebírání artefaktů", delta: 0, absolute: 3 }]);
    expect(cleanText).not.toContain("[SKILL");
  });
});

describe("parseGameTags — time tags", () => {
  it("parses [TIME:+Nd] as a day-advance mutation, normalized to minutes", () => {
    expect(parseGameTags("[TIME:+1d]").timeMutations).toEqual([{ minutes: 1440 }]);
    expect(parseGameTags("[TIME:+3d]").timeMutations).toEqual([{ minutes: 3 * 1440 }]);
  });

  it("parses [TIME:+Nh] and [TIME:+Nm] as hour/minute-advance mutations", () => {
    expect(parseGameTags("[TIME:+2h]").timeMutations).toEqual([{ minutes: 120 }]);
    expect(parseGameTags("[TIME:+15m]").timeMutations).toEqual([{ minutes: 15 }]);
  });

  it("strips an unsupported clock-time tag without producing a mutation", () => {
    const { timeMutations, cleanText } = parseGameTags("Scéna. [TIME: 14:00] Pokračuje.");
    expect(timeMutations).toEqual([]);
    expect(cleanText).not.toContain("[TIME");
  });
});

//! Shared SSE (Server-Sent Events) line reader used by all provider
//! adapters. `reqwest`'s `bytes_stream()` yields arbitrary byte chunks that
//! do not respect line boundaries — a single `data: ...` line (or even a
//! multi-byte UTF-8 codepoint) can be split across two chunks. This module
//! buffers bytes and only emits complete, newline-terminated lines.

/// Accumulates raw bytes across chunk boundaries and yields complete lines
/// (without the trailing `\n`/`\r\n`) as they become available.
#[derive(Default)]
pub struct SseLineSplitter {
    buffer: Vec<u8>,
}

impl SseLineSplitter {
    pub fn new() -> Self {
        Self { buffer: Vec::new() }
    }

    /// Feed a chunk of bytes, returning any complete lines it produced
    /// (including lines completed by bytes left over from a previous call).
    pub fn push(&mut self, chunk: &[u8]) -> Vec<String> {
        self.buffer.extend_from_slice(chunk);
        let mut lines = Vec::new();
        while let Some(pos) = self.buffer.iter().position(|&b| b == b'\n') {
            let mut line_bytes: Vec<u8> = self.buffer.drain(..=pos).collect();
            line_bytes.pop(); // drop '\n'
            if line_bytes.last() == Some(&b'\r') {
                line_bytes.pop();
            }
            lines.push(String::from_utf8_lossy(&line_bytes).into_owned());
        }
        lines
    }
}

/// Extracts the payload of an SSE `data: ...` line, if this is one.
/// Handles both `data: value` and `data:value` (no space).
pub fn parse_data_line(line: &str) -> Option<&str> {
    let rest = line.strip_prefix("data:")?;
    Some(rest.strip_prefix(' ').unwrap_or(rest))
}

/// Extracts the payload of an SSE `event: ...` line, if this is one.
pub fn parse_event_line(line: &str) -> Option<&str> {
    let rest = line.strip_prefix("event:")?;
    Some(rest.strip_prefix(' ').unwrap_or(rest).trim())
}

/// Result of interpreting one provider-specific SSE `data:` payload.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParsedEvent {
    Token(String),
    /// EXPERIMENTAL (function-calling prototype, Gemini only): the model
    /// emitted a `functionCall` part instead of (or alongside) text.
    /// Carries the raw JSON args as a string (parsed back to `Value` by the
    /// caller) so this enum can stay `Eq`-derivable for the existing tests,
    /// plus Gemini's opaque `thoughtSignature` (must be echoed back verbatim
    /// on the follow-up request or the API rejects it with HTTP 400).
    FunctionCall(String, String, Option<String>),
    Done(String),
    None,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn splits_single_chunk_with_multiple_lines() {
        let mut splitter = SseLineSplitter::new();
        let lines = splitter.push(b"data: foo\ndata: bar\n");
        assert_eq!(lines, vec!["data: foo".to_string(), "data: bar".to_string()]);
    }

    #[test]
    fn handles_line_split_across_chunk_boundary() {
        let mut splitter = SseLineSplitter::new();
        let first = splitter.push(b"data: {\"choices\":[{\"delta\":{\"con");
        assert!(first.is_empty());
        let second = splitter.push(b"tent\":\"hi\"}}]}\n");
        assert_eq!(second, vec!["data: {\"choices\":[{\"delta\":{\"content\":\"hi\"}}]}".to_string()]);
    }

    #[test]
    fn handles_crlf_line_endings() {
        let mut splitter = SseLineSplitter::new();
        let lines = splitter.push(b"data: foo\r\ndata: bar\r\n");
        assert_eq!(lines, vec!["data: foo".to_string(), "data: bar".to_string()]);
    }

    #[test]
    fn buffers_incomplete_trailing_bytes() {
        let mut splitter = SseLineSplitter::new();
        let lines = splitter.push(b"data: partial-no-newline-yet");
        assert!(lines.is_empty());
        let lines2 = splitter.push(b"\n");
        assert_eq!(lines2, vec!["data: partial-no-newline-yet".to_string()]);
    }

    #[test]
    fn parses_data_line_with_and_without_space() {
        assert_eq!(parse_data_line("data: hello"), Some("hello"));
        assert_eq!(parse_data_line("data:hello"), Some("hello"));
        assert_eq!(parse_data_line("event: foo"), None);
    }

    #[test]
    fn parses_event_line() {
        assert_eq!(parse_event_line("event: content_block_delta"), Some("content_block_delta"));
        assert_eq!(parse_event_line("data: foo"), None);
    }
}

//! Small generic file I/O commands used by frontend features that need to
//! read/write plain text files chosen via a native dialog (World Info JSON
//! import/export for lorebooks — M4). Kept separate from `cards.rs` since
//! it isn't card-specific.

use std::fs;

/// Reads a text file at `path` and returns its contents. Generic
/// counterpart to `read_card_json_file` for non-card text files (e.g.
/// SillyTavern World Info JSON).
#[tauri::command]
pub fn read_text_file(path: String) -> Result<String, String> {
    fs::read_to_string(&path).map_err(|e| format!("nepodařilo se přečíst soubor: {e}"))
}

/// Writes `contents` to a text file at `path`, overwriting it if it exists.
#[tauri::command]
pub fn write_text_file(path: String, contents: String) -> Result<(), String> {
    fs::write(&path, contents).map_err(|e| format!("nepodařilo se uložit soubor: {e}"))
}

//! DeepSeek-specific: checks the user's account balance via the official
//! `GET /user/balance` endpoint. Only meaningful for DeepSeek connections;
//! other providers return a "not supported" error.

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BalanceInfo {
    pub currency: String,
    pub total_balance: String,
    pub granted_balance: String,
    pub topped_up_balance: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UserBalance {
    pub is_available: bool,
    pub balance_infos: Vec<BalanceInfo>,
}

/// Calls DeepSeek's `GET /user/balance` endpoint. The `base_url` should be
/// the same URL the user configured for chat completions (e.g.
/// `https://api.deepseek.com/v1`). The endpoint is at `/user/balance`
/// relative to the API root (we strip `/v1` if present).
#[tauri::command]
pub async fn get_user_balance(
    connection_id: String,
    base_url: Option<String>,
) -> Result<UserBalance, String> {
    let api_key = super::secrets::get_api_key(&connection_id)?
        .ok_or_else(|| "API key not found for this connection".to_string())?;

    // The /user/balance endpoint lives at the API root, not under /v1.
    // If the user's base_url is e.g. "https://api.deepseek.com/v1",
    // we need "https://api.deepseek.com/user/balance".
    let root = base_url
        .unwrap_or_else(|| "https://api.deepseek.com".to_string())
        .trim_end_matches('/')
        .trim_end_matches("/v1")
        .to_string();
    let url = format!("{root}/user/balance");

    let client = reqwest::Client::new();
    let resp = client
        .get(&url)
        .bearer_auth(&api_key)
        .send()
        .await
        .map_err(|e| format!("HTTP error: {e}"))?;

    let status = resp.status();
    if !status.is_success() {
        let body = resp.text().await.unwrap_or_default();
        return Err(format!("API error ({status}): {body}"));
    }

    let balance: UserBalance = resp
        .json()
        .await
        .map_err(|e| format!("Failed to parse balance response: {e}"))?;

    Ok(balance)
}

//! Sync journal I/O commands — thin Rust layer for the TS sync engine.
//! The TypeScript side owns the journal format, rotation logic, and merge
//! semantics; these commands are just generic filesystem primitives.

use std::fs;
use std::io::Write;
use std::path::Path;

/// Appends `line` + "\n" to `path`, creating the file (and its parent
/// directories) if they don't exist yet. Returns the new file size in bytes
/// (so the TS side can trigger rotation when it crosses ~10 MB).
#[tauri::command]
pub fn append_journal_line(path: String, line: String) -> Result<u64, String> {
    let p = Path::new(&path);
    if let Some(parent) = p.parent() {
        fs::create_dir_all(parent)
            .map_err(|e| format!("cannot create sync folder: {e}"))?;
    }
    let mut f = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(p)
        .map_err(|e| format!("cannot open journal: {e}"))?;
    writeln!(f, "{line}").map_err(|e| format!("cannot write journal: {e}"))?;
    let meta = f.metadata().map_err(|e| format!("cannot stat journal: {e}"))?;
    Ok(meta.len())
}

/// Lists immediate children of `dir` with `name`, `is_dir`, and `size_bytes`.
/// Returns an empty array when the directory does not exist (sync disabled /
/// folder not yet created) so the frontend never sees a hard error.
#[tauri::command]
pub fn list_sync_entries(dir: String) -> Result<Vec<SyncDirEntry>, String> {
    let p = Path::new(&dir);
    if !p.is_dir() {
        return Ok(Vec::new());
    }
    let mut entries = Vec::new();
    let iter = fs::read_dir(p).map_err(|e| format!("cannot read sync folder: {e}"))?;
    for entry in iter {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let meta = match entry.metadata() {
            Ok(m) => m,
            Err(_) => continue,
        };
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.starts_with('.') {
            continue; // skip hidden files/folders
        }
        entries.push(SyncDirEntry {
            name,
            is_dir: meta.is_dir(),
            size_bytes: meta.len(),
        });
    }
    Ok(entries)
}

/// Reads up to `max_bytes` from `path` starting at `start_byte`, returning
/// (raw_text, next_start_byte) where next_start_byte is the position after
/// the last byte read (or `null` when EOF is reached). Used by the journal
/// reader to incrementally consume large journals.
#[tauri::command]
pub fn read_journal_chunk(
    path: String,
    start_byte: u64,
    max_bytes: u64,
) -> Result<JournalChunk, String> {
    use std::io::Read;
    let mut f = fs::File::open(&path).map_err(|e| format!("cannot open journal for reading: {e}"))?;
    let total = f.metadata().map_err(|e| format!("cannot stat journal: {e}"))?.len();
    if start_byte >= total {
        return Ok(JournalChunk {
            text: String::new(),
            next_start_byte: None,
            total_bytes: total,
        });
    }
    use std::io::Seek;
    f.seek(std::io::SeekFrom::Start(start_byte))
        .map_err(|e| format!("cannot seek journal: {e}"))?;
    let limit = std::cmp::min(max_bytes as usize, (total - start_byte) as usize);
    let mut buf = vec![0u8; limit];
    let n = f.read(&mut buf).map_err(|e| format!("cannot read journal: {e}"))?;
    buf.truncate(n);
    // Extend to the next newline so we never split a line.
    if (start_byte + n as u64) < total {
        let mut extra = Vec::new();
        let mut byte_buf = [0u8; 1];
        loop {
            match f.read(&mut byte_buf) {
                Ok(0) => break,
                Ok(1) => {
                    extra.push(byte_buf[0]);
                    if byte_buf[0] == b'\n' {
                        break;
                    }
                }
                Ok(_) => break, // buffer is 1 byte, only 0/1 possible
                Err(_) => break,
            }
        }
        buf.extend(&extra);
    }
    let text = String::from_utf8_lossy(&buf).into_owned();
    let end = start_byte + buf.len() as u64;
    Ok(JournalChunk {
        text,
        next_start_byte: if end < total { Some(end) } else { None },
        total_bytes: total,
    })
}

/// Deletes a file — used by the journal reader to clean up fully-processed
/// rotated journals after they've been consumed.
#[tauri::command]
pub fn delete_sync_file(path: String) -> Result<(), String> {
    match fs::remove_file(&path) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(e) => Err(format!("cannot delete sync file: {e}")),
    }
}

#[derive(serde::Serialize)]
pub struct SyncDirEntry {
    pub name: String,
    pub is_dir: bool,
    pub size_bytes: u64,
}

#[derive(serde::Serialize)]
pub struct JournalChunk {
    pub text: String,
    /// `null` when this chunk reached EOF.
    pub next_start_byte: Option<u64>,
    pub total_bytes: u64,
}

//! Embedding endpoints for the semantic memory layer. Claude has no
//! embedding API, so chats whose (extraction) connection is Claude simply
//! skip vector retrieval — the caller treats `NotSupported` as "feature
//! off", not as an error to surface.

use serde_json::json;

use super::{check_status, ProviderError};

const GEMINI_EMBEDDING_MODEL: &str = "gemini-embedding-2";
/// gemini-embedding-2 defaults to 3072 dims; 768 keeps storage/compute
/// small with negligible retrieval quality loss at this scale.
const GEMINI_OUTPUT_DIMS: u32 = 768;
const OPENAI_EMBEDDING_MODEL: &str = "text-embedding-3-small";

/// Both APIs cap batch sizes; 100 is safely under either limit.
const CHUNK_SIZE: usize = 100;

/// Returns one vector per input text, in input order, plus the model id
/// that produced them (stored alongside each vector so a model switch can
/// invalidate stale rows). `model_override` (the `embedding_model` setting)
/// replaces the per-provider default when set.
pub async fn embed_texts(
    provider: &str,
    base_url: Option<&str>,
    api_key: &str,
    model_override: Option<&str>,
    texts: &[String],
) -> Result<(String, Vec<Vec<f32>>), ProviderError> {
    let client = reqwest::Client::new();
    let mut vectors: Vec<Vec<f32>> = Vec::with_capacity(texts.len());
    let override_trimmed = model_override.map(str::trim).filter(|m| !m.is_empty());

    let model = match provider {
        "gemini" => {
            let model = override_trimmed.unwrap_or(GEMINI_EMBEDDING_MODEL);
            for chunk in texts.chunks(CHUNK_SIZE) {
                let requests: Vec<_> = chunk
                    .iter()
                    .map(|t| {
                        json!({
                            "model": format!("models/{model}"),
                            "content": { "parts": [{ "text": t }] },
                            "outputDimensionality": GEMINI_OUTPUT_DIMS
                        })
                    })
                    .collect();
                let url = format!(
                    "https://generativelanguage.googleapis.com/v1beta/models/{model}:batchEmbedContents"
                );
                let body: serde_json::Value = check_status(
                    client
                        .post(url)
                        .header("x-goog-api-key", api_key)
                        .json(&json!({ "requests": requests }))
                        .send()
                        .await?,
                )
                .await?;
                let embeddings = body["embeddings"].as_array().cloned().unwrap_or_default();
                if embeddings.len() != chunk.len() {
                    return Err(incomplete());
                }
                for e in &embeddings {
                    vectors.push(to_f32_vec(&e["values"])?);
                }
            }
            model
        }
        "openai" => {
            let model = override_trimmed.unwrap_or(OPENAI_EMBEDDING_MODEL);
            let base = base_url
                .unwrap_or("https://api.openai.com/v1")
                .trim_end_matches('/');
            for chunk in texts.chunks(CHUNK_SIZE) {
                let body: serde_json::Value = check_status(
                    client
                        .post(format!("{base}/embeddings"))
                        .bearer_auth(api_key)
                        .json(&json!({ "model": model, "input": chunk }))
                        .send()
                        .await?,
                )
                .await?;
                let mut data = body["data"].as_array().cloned().unwrap_or_default();
                data.sort_by_key(|d| d["index"].as_i64().unwrap_or(0));
                if data.len() != chunk.len() {
                    return Err(incomplete());
                }
                for d in &data {
                    vectors.push(to_f32_vec(&d["embedding"])?);
                }
            }
            model
        }
        other => {
            return Err(ProviderError::NotSupported(format!(
                "provider '{other}' nepodporuje embeddingy"
            )))
        }
    };

    Ok((model.to_string(), vectors))
}

fn to_f32_vec(values: &serde_json::Value) -> Result<Vec<f32>, ProviderError> {
    values
        .as_array()
        .map(|arr| arr.iter().filter_map(|v| v.as_f64()).map(|v| v as f32).collect())
        .filter(|v: &Vec<f32>| !v.is_empty())
        .ok_or_else(incomplete)
}

fn incomplete() -> ProviderError {
    ProviderError::Api {
        status: 0,
        message: "embedding API vrátila neúplnou odpověď".to_string(),
    }
}

//! Character card import/export commands. Reads/writes the embedded PNG
//! metadata via `png_card` and manages the on-disk copies of card avatars
//! kept under `<app_data_dir>/avatars/`.

use std::fs;
use std::path::PathBuf;

use serde::Serialize;
use tauri::{AppHandle, Manager};

use crate::png_card;

fn avatars_dir(app: &AppHandle) -> Result<PathBuf, String> {
    let base = app
        .path()
        .app_data_dir()
        .map_err(|e| format!("nepodařilo se najít adresář aplikace: {e}"))?;
    let dir = base.join("avatars");
    fs::create_dir_all(&dir).map_err(|e| format!("nepodařilo se vytvořit adresář avatarů: {e}"))?;
    Ok(dir)
}

#[derive(Debug, Serialize)]
pub struct ImportCardResult {
    pub card_json: String,
    pub avatar_saved_to: String,
}

/// Reads a character card from a PNG file at `path` (any location the user
/// picked via a file dialog) and stores a copy of that PNG under the app's
/// avatars directory, named by a freshly generated id — independent of
/// whatever character id the frontend later assigns the imported card.
#[tauri::command]
pub fn import_card_png(app: AppHandle, path: String) -> Result<ImportCardResult, String> {
    let bytes = fs::read(&path).map_err(|e| format!("nepodařilo se přečíst soubor: {e}"))?;
    let card_json = png_card::read_card_json(&bytes).map_err(|e| e.to_string())?;

    let dir = avatars_dir(&app)?;
    let filename = format!("{}.png", uuid::Uuid::new_v4());
    let dest = dir.join(&filename);
    fs::write(&dest, &bytes).map_err(|e| format!("nepodařilo se uložit avatar: {e}"))?;

    Ok(ImportCardResult {
        card_json,
        avatar_saved_to: dest.to_string_lossy().to_string(),
    })
}

/// Reads a plain (non-PNG) JSON card file and returns its raw text. Used by
/// `cardImport.ts` for JSON-only card imports (no avatar image involved).
#[tauri::command]
pub fn read_card_json_file(path: String) -> Result<String, String> {
    fs::read_to_string(&path).map_err(|e| format!("nepodařilo se přečíst soubor: {e}"))
}

/// Merges `card_json` into the PNG at `avatar_path` and writes the result
/// to `out_path`. Used for "export character to PNG".
#[tauri::command]
pub fn export_card_png(card_json: String, avatar_path: String, out_path: String) -> Result<(), String> {
    let bytes = fs::read(&avatar_path).map_err(|e| format!("nepodařilo se přečíst avatar: {e}"))?;
    let with_card = png_card::write_card_json(&bytes, &card_json).map_err(|e| e.to_string())?;
    fs::write(&out_path, with_card).map_err(|e| format!("nepodařilo se uložit soubor: {e}"))?;
    Ok(())
}

/// Ensures a placeholder avatar PNG exists under the app data directory and
/// returns its path. Used as the source image for exporting/creating
/// characters that were imported from plain JSON (no original PNG) or
/// created from scratch in the editor.
#[tauri::command]
pub fn ensure_placeholder_avatar(app: AppHandle) -> Result<String, String> {
    let dir = avatars_dir(&app)?;
    let dest = dir.join("_placeholder.png");
    if !dest.exists() {
        fs::write(&dest, png_card::placeholder_png())
            .map_err(|e| format!("nepodařilo se uložit výchozí avatar: {e}"))?;
    }
    Ok(dest.to_string_lossy().to_string())
}

