252	        // up for Gemini per the current scope — the other providers ignore
253	        // it and never emit `StreamEvent::FunctionCall`.
254	        "gemini" => gemini::stream(connection, api_key, messages, cancel, tx.clone(), tools).await,
255	        "openai" => openai::stream(connection, api_key, messages, cancel, tx.clone()).await,
256	        "claude" => claude::stream(connection, api_key, messages, cancel, tx.clone()).await,
257	        other => Err(ProviderError::NotSupported(format!(
258	            "provider '{other}' zatím není podporován"
259	        ))),
260	    };
261	    if let Err(err) = result {
262	        let _ = tx.send(StreamEvent::Error {
263	            message: err.to_string(),
264	            retryable: false,
265	        });
266	    }
267	}
