269	/// Non-streaming completion, used by `chat_complete`. Internally drives the
270	/// same `stream_chat` path and concatenates the tokens.
271	pub async fn complete(
272	    connection: &ConnectionDto,
273	    api_key: &str,
274	    messages: &[ChatMessage],
275	) -> Result<String, ProviderError> {
276	    let (tx, mut rx) = mpsc::unbounded_channel::<StreamEvent>();
277	    let cancel = CancellationToken::new();
278	
279	    let conn = connection.clone();
280	    let key = api_key.to_string();
281	    let msgs = messages.to_vec();
282	    tokio::spawn(async move {
283	        stream_chat(&conn, &key, &msgs, cancel, tx, false).await;
284	    });
285	
286	    let mut text = String::new();
287	    while let Some(event) = rx.recv().await {
288	        match event {
289	            StreamEvent::Token { text: t } => text.push_str(&t),
290	            StreamEvent::Done { .. } => break,
291	            StreamEvent::Error { message, .. } => {
292	                return Err(ProviderError::Api {
293	                    status: 0,
294	                    message,
295	                })
296	            }
297	            StreamEvent::Start => {}
298	            // `complete()` never requests tools, so this never fires — but
299	            // match exhaustively rather than `_ =>` so a future StreamEvent
300	            // variant fails to compile here instead of being silently
301	            // dropped.
302	            StreamEvent::FunctionCall { .. } => {}
303	        }
304	    }
305	    Ok(text)
306	}

