  9	fn build_body(connection: &ConnectionDto, messages: &[ChatMessage]) -> Value {
 10	    let msgs: Vec<Value> = messages
 11	        .iter()
 12	        .map(|m| {
 13	            let role = match m.role {
 14	                Role::System => "system",
 15	                Role::User => "user",
 16	                Role::Assistant => "assistant",
 17	            };
 18	            json!({ "role": role, "content": m.content })
 19	        })
 20	        .collect();
 21	
 22	    let mut body = json!({
 23	        "model": connection.model,
 24	        "messages": msgs,
 25	        "temperature": connection.temperature,
 26	        "top_p": connection.top_p,
 27	        "max_tokens": connection.max_tokens,
 28	        "stream": true,
 29	    });
 30	    if let Some(fp) = connection.frequency_penalty {
 31	        body["frequency_penalty"] = json!(fp);
 32	    }
 33	    if let Some(pp) = connection.presence_penalty {
 34	        body["presence_penalty"] = json!(pp);
 35	    }
 36	    body
 37	}
