 39	/// Parses one OpenAI-compatible `data: {...}` SSE payload (also handles the
 40	/// literal `data: [DONE]` terminator).
 41	pub fn parse_data(data: &str) -> ParsedEvent {
 42	    if data == "[DONE]" {
 43	        return ParsedEvent::Done("stop".to_string());
 44	    }
 45	
 46	    let v: Value = match serde_json::from_str(data) {
 47	        Ok(v) => v,
 48	        Err(_) => return ParsedEvent::None,
 49	    };
 50	
 51	    if let Some(text) = v["choices"][0]["delta"]["content"].as_str() {
 52	        if !text.is_empty() {
 53	            return ParsedEvent::Token(text.to_string());
 54	        }
 55	    }
 56	    if let Some(reason) = v["choices"][0]["finish_reason"].as_str() {
 57	        return ParsedEvent::Done(reason.to_string());
 58	    }
 59	    ParsedEvent::None
 60	}
