 62	/// OpenAI-compatible: ChatGPT, DeepSeek, OpenRouter — differ only by
 63	/// base_url + model.
 64	pub async fn stream(
 65	    connection: &ConnectionDto,
 66	    api_key: &str,
 67	    messages: &[ChatMessage],
 68	    cancel: CancellationToken,
 69	    tx: mpsc::UnboundedSender<StreamEvent>,
 70	) -> Result<(), ProviderError> {
 71	    let client = reqwest::Client::new();
 72	
 73	    let base_url = connection
 74	        .base_url
 75	        .clone()
 76	        .unwrap_or_else(|| "https://api.openai.com/v1".to_string());
 77	    let base_url = base_url.trim_end_matches('/');
 78	    let url = format!("{base_url}/chat/completions");
 79	
 80	    let body = build_body(connection, messages);
 81	
 82	    let res = client
 83	        .post(&url)
 84	        .bearer_auth(api_key)
 85	        .json(&body)
 86	        .send()
 87	        .await?;
 88	
 89	    let status = res.status();
 90	    if !status.is_success() {
 91	        let message = res.text().await.unwrap_or_default();
 92	        let retryable = status.as_u16() == 429 || status.as_u16() >= 500;
 93	        let _ = tx.send(StreamEvent::Error { message, retryable });
 94	        return Ok(());
 95	    }
 96	
 97	    let mut stream = res.bytes_stream();
 98	    let mut splitter = SseLineSplitter::new();
 99	
100	    loop {
101	        tokio::select! {
102	            _ = cancel.cancelled() => return Ok(()),
103	            chunk = stream.next() => {
104	                match chunk {
105	                    None => break,
106	                    Some(Err(e)) => {
107	                        let _ = tx.send(StreamEvent::Error { message: e.to_string(), retryable: true });
108	                        return Ok(());
109	                    }
110	                    Some(Ok(bytes)) => {
111	                        for line in splitter.push(&bytes) {
112	                            let Some(data) = parse_data_line(&line) else { continue };
113	                            match parse_data(data) {
114	                                ParsedEvent::Token(text) => {
115	                                    let _ = tx.send(StreamEvent::Token { text });
116	                                }
117	                                ParsedEvent::Done(finish_reason) => {
118	                                    let _ = tx.send(StreamEvent::Done { finish_reason });
119	                                    return Ok(());
120	                                }
121	                                // Function calling is not wired up for this
122	                                // provider (Gemini-only prototype scope).
123	                                ParsedEvent::FunctionCall(..) => {}
124	                                ParsedEvent::None => {}
125	                            }
126	                        }
127	                    }
128	                }
129	            }
130	        }
131	    }
132	
133	    let _ = tx.send(StreamEvent::Done { finish_reason: "stop".to_string() });
134	    Ok(())
135	}
