 37	fn build_body(connection: &ConnectionDto, messages: &[ChatMessage], tools: bool) -> Value {
 38	    let system_instruction = messages
 39	        .iter()
 40	        .find(|m| matches!(m.role, Role::System))
 41	        .map(|m| json!({ "parts": [{ "text": m.content }] }));
 42	
 43	    let contents: Vec<Value> = messages
 44	        .iter()
 45	        .filter(|m| !matches!(m.role, Role::System))
 46	        .map(|m| {
 47	            // EXPERIMENTAL: function-call / function-response turns carry no
 48	            // plain text — they replay the tool round-trip back to Gemini in
 49	            // its expected wire shape instead of the usual `{text}` part.
 50	            if let Some(fc) = &m.function_call {
 51	                let mut part = json!({ "functionCall": { "name": fc.name, "args": fc.args } });
 52	                // Must sit alongside functionCall on the part, matching how
 53	                // Gemini originally sent it (see parse_data) — not nested
 54	                // inside functionCall itself.
 55	                if let Some(sig) = &fc.thought_signature {
 56	                    part["thoughtSignature"] = json!(sig);
 57	                }
 58	                return json!({
 59	                    "role": "model",
 60	                    "parts": [part]
 61	                });
 62	            }
 63	            if let Some(fr) = &m.function_response {
 64	                return json!({
 65	                    "role": "user",
 66	                    "parts": [{ "functionResponse": { "name": fr.name, "response": fr.response } }]
 67	                });
 68	            }
 69	            let role = match m.role {
 70	                Role::Assistant => "model",
 71	                _ => "user",
 72	            };
 73	            json!({ "role": role, "parts": [{ "text": m.content }] })
 74	        })
 75	        .collect();
 76	
 77	    let mut body = json!({
 78	        "contents": contents,
 79	        "generationConfig": {
 80	            "temperature": connection.temperature,
 81	            "topP": connection.top_p,
 82	            "maxOutputTokens": connection.max_tokens,
 83	        }
 84	    });
 85	    if let Some(tk) = connection.top_k {
 86	        body["generationConfig"]["topK"] = json!(tk);
 87	    }
 88	    // Gemini 2.5+/3.x models default to dynamic "thinking", which adds long
 89	    // pauses before each reply — useless for roleplay streaming. Budget 0
 90	    // disables it; older models (2.0 and below) reject the field.
 91	    let m = connection.model.as_str();
 92	    if m.contains("-2.5") || m.contains("-3") {
 93	        body["generationConfig"]["thinkingConfig"] = json!({ "thinkingBudget": 0 });
 94	    }
 95	    if let Some(sys) = system_instruction {
 96	        body["systemInstruction"] = sys;
 97	    }
 98	    if tools {
 99	        body["tools"] = tool_declarations();
100	    }
101	    body
102	}
