104	/// Parses one Gemini `data: {...}` SSE payload.
105	pub fn parse_data(data: &str) -> ParsedEvent {
106	    let v: Value = match serde_json::from_str(data) {
107	        Ok(v) => v,
108	        Err(_) => return ParsedEvent::None,
109	    };
110	
111	    if let Some(parts) = v["candidates"][0]["content"]["parts"].as_array() {
112	        // EXPERIMENTAL: a `functionCall` part takes priority over any text
113	        // part in the same chunk — Gemini doesn't mix narrative text with a
114	        // tool call in one part, but checking first keeps this robust either
115	        // way.
116	        for part in parts {
117	            if let Some(name) = part["functionCall"]["name"].as_str() {
118	                let args = part["functionCall"]["args"].to_string();
119	                // Gemini attaches this at the *part* level, alongside (not
120	                // inside) functionCall — must be replayed verbatim on the
121	                // follow-up request or the API rejects it with HTTP 400.
122	                let thought_signature = part["thoughtSignature"].as_str().map(|s| s.to_string());
123	                return ParsedEvent::FunctionCall(name.to_string(), args, thought_signature);
124	            }
125	        }
126	        let text: String = parts.iter().filter_map(|p| p["text"].as_str()).collect();
127	        if !text.is_empty() {
128	            return ParsedEvent::Token(text);
129	        }
130	    }
131	    if let Some(reason) = v["candidates"][0]["finishReason"].as_str() {
132	        return ParsedEvent::Done(reason.to_string());
133	    }
134	    ParsedEvent::None
135	}
