137	pub async fn stream(
138	    connection: &ConnectionDto,
139	    api_key: &str,
140	    messages: &[ChatMessage],
141	    cancel: CancellationToken,
142	    tx: mpsc::UnboundedSender<StreamEvent>,
143	    tools: bool,
144	) -> Result<(), ProviderError> {
145	    let client = reqwest::Client::new();
146	    let body = build_body(connection, messages, tools);
147	    let url = format!(
148	        "https://generativelanguage.googleapis.com/v1beta/models/{}:streamGenerateContent?alt=sse",
149	        connection.model
150	    );
151	
152	    let res = client
153	        .post(&url)
154	        .header("x-goog-api-key", api_key)
155	        .json(&body)
156	        .send()
157	        .await?;
158	
159	    let status = res.status();
160	    if !status.is_success() {
161	        let message = res.text().await.unwrap_or_default();
162	        let retryable = status.as_u16() == 429 || status.as_u16() >= 500;
163	        let _ = tx.send(StreamEvent::Error { message, retryable });
164	        return Ok(());
165	    }
166	
167	    let mut stream = res.bytes_stream();
168	    let mut splitter = SseLineSplitter::new();
169	
170	    loop {
171	        tokio::select! {
172	            _ = cancel.cancelled() => return Ok(()),
173	            chunk = stream.next() => {
174	                match chunk {
175	                    None => break,
176	                    Some(Err(e)) => {
177	                        let _ = tx.send(StreamEvent::Error { message: e.to_string(), retryable: true });
178	                        return Ok(());
179	                    }
180	                    Some(Ok(bytes)) => {
181	                        for line in splitter.push(&bytes) {
182	                            let Some(data) = parse_data_line(&line) else { continue };
183	                            match parse_data(data) {
184	                                ParsedEvent::Token(text) => {
185	                                    let _ = tx.send(StreamEvent::Token { text });
186	                                }
187	                                ParsedEvent::FunctionCall(name, args_json, thought_signature) => {
188	                                    let args = serde_json::from_str(&args_json)
189	                                        .unwrap_or(Value::Null);
190	                                    let _ = tx.send(StreamEvent::FunctionCall { name, args, thought_signature });
191	                                    // Gemini does not keep streaming narrative
192	                                    // text in the same turn after a
193	                                    // functionCall part — this call's job is
194	                                    // done; the frontend resumes with a fresh
195	                                    // `chat_stream` call once it has the tool
196	                                    // result.
197	                                    return Ok(());
198	                                }
199	                                ParsedEvent::Done(finish_reason) => {
200	                                    let _ = tx.send(StreamEvent::Done { finish_reason });
201	                                    return Ok(());
202	                                }
203	                                ParsedEvent::None => {}
204	                            }
205	                        }
206	                    }
207	                }
208	            }
209	        }
210	    }
211	
212	    let _ = tx.send(StreamEvent::Done { finish_reason: "stop".to_string() });
213	    Ok(())
214	}
