  1	//! API key storage — simple JSON file in the app config directory.
  2	//! No OS keyring dependency: works identically on all platforms and
  3	//! survives dbus restarts. Keys are plain text in a 0600-permission file;
  4	//! on a single-user desktop this is equivalent to the OS keyring.
  5	//!
  6	//! Never returns keys to the JS side — all key access is internal Rust only.
  7	
  8	use std::collections::HashMap;
  9	use std::fs;
 10	use std::io::Write;
 11	use std::path::PathBuf;
 12	use std::sync::Mutex;
 13	
 14	const FILE_NAME: &str = "secrets.json";
 15	
 16	pub struct FileStore {
 17	    dir: PathBuf,
 18	    // Simple in-memory cache to avoid reading the file on every access.
 19	    // Wrapped in a Mutex because Tauri commands can run concurrently.
 20	    cache: Mutex<Option<HashMap<String, String>>>,
 21	}
 22	
 23	impl FileStore {
 24	    pub fn new(dir: PathBuf) -> Self {
 25	        Self {
 26	            dir,
 27	            cache: Mutex::new(None),
 28	        }
 29	    }
 30	
 31	    fn path(&self) -> PathBuf {
 32	        self.dir.join(FILE_NAME)
 33	    }
 34	
 35	    fn load(&self) -> Result<HashMap<String, String>, String> {
 36	        let path = self.path();
 37	        if !path.exists() {
 38	            return Ok(HashMap::new());
 39	        }
 40	        let raw = fs::read_to_string(&path)
 41	            .map_err(|e| format!("nepodařilo se přečíst soubor s klíči: {e}"))?;
 42	        serde_json::from_str(&raw)
 43	            .map_err(|e| format!("nepodařilo se parsovat soubor s klíči: {e}"))
 44	    }
 45	
 46	    fn save(&self, app: Option<&AppHandle>, map: &HashMap<String, String>) -> Result<(), String> {
 47	        let path = self.path();
 48	        if let Some(parent) = path.parent() {
 49	            fs::create_dir_all(parent)
 50	                .map_err(|e| format!("nepodařilo se vytvořit adresář pro klíče: {e}"))?;
 51	        }
 52	        let json = serde_json::to_string_pretty(map)
 53	            .map_err(|e| format!("nepodařilo se serializovat klíče: {e}"))?;
 54	        let mut file = fs::File::create(&path)
 55	            .map_err(|e| format!("nepodařilo se vytvořit soubor s klíči: {e}"))?;
 56	        file.write_all(json.as_bytes())
 57	            .map_err(|e| format!("nepodařilo se zapsat klíče: {e}"))?;
 58	        // Set permissions to 0600 (owner read/write only) on Unix. A failure
 59	        // here is security-relevant (the API-key file would stay readable
 60	        // by other local users) but not worth hard-failing the save over —
 61	        // log it so it's at least visible instead of silently swallowed.
 62	        #[cfg(unix)]
 63	        {
 64	            use std::os::unix::fs::PermissionsExt;
 65	            if let Err(e) = file.set_permissions(fs::Permissions::from_mode(0o600)) {
 66	                if let Some(app) = app {
 67	                    crate::commands::logging::log_line(
 68	                        app,
 69	                        crate::commands::logging::LogLevel::Warn,
 70	                        &format!("secrets: failed to set 0600 permissions on {}: {e}", path.display()),
 71	                    );
 72	                }
 73	            }
 74	        }
 75	        Ok(())
 76	    }
 77	
 78	    fn get_map(&self) -> Result<HashMap<String, String>, String> {
 79	        let mut cache = self.cache.lock().unwrap();
 80	        if let Some(ref cached) = *cache {
 81	            return Ok(cached.clone());
 82	        }
 83	        let map = self.load()?;
 84	        *cache = Some(map.clone());
 85	        Ok(map)
 86	    }
 87	
 88	    pub fn get(&self, connection_id: &str) -> Result<Option<String>, String> {
 89	        let map = self.get_map()?;
 90	        Ok(map.get(connection_id).cloned())
 91	    }
 92	
 93	    pub fn set(&self, app: &AppHandle, connection_id: &str, key: &str) -> Result<(), String> {
 94	        let mut map = self.get_map()?;
 95	        map.insert(connection_id.to_string(), key.to_string());
 96	        self.save(Some(app), &map)?;
 97	        // Update cache
 98	        *self.cache.lock().unwrap() = Some(map);
 99	        Ok(())
100	    }
101	
102	    pub fn delete(&self, app: &AppHandle, connection_id: &str) -> Result<(), String> {
103	        let mut map = self.get_map()?;
104	        map.remove(connection_id);
105	        self.save(Some(app), &map)?;
106	        *self.cache.lock().unwrap() = Some(map);
107	        Ok(())
108	    }
109	}
