142	/// Internal helper for other commands (e.g. chat_complete) that need the
143	/// actual key value. Never exposed as a Tauri command itself.
144	pub fn get_api_key(connection_id: &str) -> Result<Option<String>, String> {
145	    // This is called from async contexts without AppHandle — fall back to
146	    // direct file read.
147	    let dir = dirs_next().ok_or("nepodařilo se najít domovský adresář")?;
148	    let store = FileStore::new(dir);
149	    store.get(connection_id)
150	}
151	
152	fn dirs_next() -> Option<PathBuf> {
153	    // Use the same config dir logic as tauri would
154	    if let Ok(dir) = std::env::var("APPDATA") {
155	        Some(PathBuf::from(dir).join("com.morthos.mysillytavern"))
156	    } else if let Some(home) = dirs::home_dir() {
157	        if cfg!(target_os = "macos") {
158	            Some(home.join("Library/Application Support/com.morthos.mysillytavern"))
159	        } else {
160	            // Linux and others: XDG_CONFIG_HOME or ~/.config
161	            if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
162	                Some(PathBuf::from(xdg).join("com.morthos.mysillytavern"))
163	            } else {
164	                Some(home.join(".config/com.morthos.mysillytavern"))
165	            }
166	        }
167	    } else {
168	        None
169	    }
170	}
