172	/// Initialise the secrets store with the app's config directory.
173	/// Called from `run()` before any command can access keys.
174	pub fn init_store(app: &AppHandle) -> Result<(), String> {
175	    let dir = app_secrets_dir(app)?;
176	    let store = FileStore::new(dir);
177	    app.manage(store);
178	    Ok(())
179	}

