 87	/// Streams a chat completion token-by-token over `on_event`. Emits exactly
 88	/// one `Start`, then zero or more `Token`s, then exactly one `Done` or
 89	/// `Error` (unless aborted via `chat_abort`, in which case the stream just
 90	/// stops silently).
 91	#[tauri::command]
 92	pub async fn chat_stream(
 93	    request_id: String,
 94	    connection: ConnectionDto,
 95	    messages: Vec<ChatMessage>,
 96	    on_event: Channel<StreamEvent>,
 97	    registry: State<'_, StreamRegistry>,
 98	    // EXPERIMENTAL (function-calling prototype): when true and the
 99	    // connection's provider is Gemini, offers the `get_item_detail` tool
100	    // and may terminate this call early with a `FunctionCall` event instead
101	    // of `Done` — see `StreamEvent::FunctionCall` doc comment. `Option` (not
102	    // a plain `bool`) so existing call sites that don't pass this argument
103	    // at all still deserialize fine and default to no-tools behavior.
104	    tools: Option<bool>,
105	) -> Result<(), String> {
106	    let tools = tools.unwrap_or(false);
107	    let api_key = match get_api_key(&connection.id) {
108	        Ok(Some(key)) => key,
109	        Ok(None) => {
110	            let _ = on_event.send(StreamEvent::Error {
111	                message: "Pro toto připojení není uložen žádný API klíč.".to_string(),
112	                retryable: false,
113	            });
114	            return Ok(());
115	        }
116	        Err(err) => {
117	            let _ = on_event.send(StreamEvent::Error {
118	                message: err.to_string(),
119	                retryable: false,
120	            });
121	            return Ok(());
122	        }
123	    };
124	
125	    let cancel = CancellationToken::new();
126	    registry.insert(request_id.clone(), cancel.clone());
127	
128	    let _ = on_event.send(StreamEvent::Start);
129	
130	    let (tx, mut rx) = mpsc::unbounded_channel::<StreamEvent>();
131	    let task = tokio::spawn(async move {
132	        providers::stream_chat(&connection, &api_key, &messages, cancel, tx, tools).await;
133	    });
134	
135	    let mut saw_terminal = false;
136	    while let Some(event) = rx.recv().await {
137	        // `FunctionCall` ends this `chat_stream` call the same way `Done`/
138	        // `Error` do (see its doc comment) — the frontend must issue a new
139	        // `chat_stream` call to resume generation once it has the result.
140	        let is_terminal = matches!(
141	            event,
142	            StreamEvent::Done { .. } | StreamEvent::Error { .. } | StreamEvent::FunctionCall { .. }
143	        );
144	        let _ = on_event.send(event);
145	        if is_terminal {
146	            saw_terminal = true;
147	            break;
148	        }
149	    }
150	
151	    let _ = task.await;
152	    // If `chat_abort` already removed the registry entry, this stream was
153	    // cancelled deliberately — the frontend already knows and doesn't need
154	    // a synthetic error. Otherwise, if we never saw a terminal event, the
155	    // stream ended abnormally (bug in a provider adapter) and the frontend
156	    // would otherwise spin forever waiting for one.
157	    let was_aborted = registry.remove(&request_id).is_none();
158	    if !saw_terminal && !was_aborted {
159	        let _ = on_event.send(StreamEvent::Error {
160	            message: "Stream skončil bez odpovědi.".to_string(),
161	            retryable: true,
162	        });
163	    }
164	
165	    Ok(())
166	}
