168	/// Cancels a running `chat_stream` by request id. No-op if it already
169	/// finished or never existed.
170	#[tauri::command]
171	pub fn chat_abort(request_id: String, registry: State<'_, StreamRegistry>) -> Result<(), String> {
172	    if let Some(token) = registry.remove(&request_id) {
173	        token.cancel();
174	    }
175	    Ok(())
176	}

