 57	/// Starts a background export job. Chunks are pre-computed by the frontend
 58	/// and passed as JSON. The command spawns a background task that processes
 59	/// each chunk through the AI and assembles the final HTML file.
 60	#[tauri::command]
 61	pub async fn start_export(
 62	    app: AppHandle,
 63	    registry: State<'_, ExportRegistry>,
 64	    job_id: String,
 65	    connection: ConnectionDto,
 66	    chunks_json: String,
 67	    theme: String,
 68	    format: String,
 69	    include_illustrations: bool,
 70	    output_dir: String,
 71	) -> Result<(), String> {
 72	    let chunks: Vec<ChunkInput> =
 73	        serde_json::from_str(&chunks_json).map_err(|e| format!("invalid chunks_json: {e}"))?;
 74	    let total = chunks.len() as i32;
 75	
 76	    let cancel = CancellationToken::new();
 77	    let cancel_clone = cancel.clone();
 78	
 79	    let job = ExportJob {
 80	        job_id: job_id.clone(),
 81	        status: "running".to_string(),
 82	        progress: 0,
 83	        total_chunks: total,
 84	        current_chunk: 0,
 85	        output_path: None,
 86	        cancel,
 87	    };
 88	
 89	    registry
 90	        .0
 91	        .lock()
 92	        .map_err(|e| e.to_string())?
 93	        .insert(job_id.clone(), job);
 94	
 95	    // Resolve output directory
 96	    let resolved_output_dir = if output_dir.is_empty() {
 97	        app.path()
 98	            .app_data_dir()
 99	            .map(|p| p.join("chronicles"))
100	            .map(|p| p.to_string_lossy().to_string())
101	            .unwrap_or_else(|_| ".".to_string())
102	    } else {
103	        output_dir
104	    };
105	
106	    let reg = Arc::clone(&registry.0);
