134	/// Resumes a previously interrupted export job. Reads the already-processed
135	/// chunks from `chunks_json` and continues from `current_chunk`.
136	#[tauri::command]
137	pub async fn resume_export(
138	    app: AppHandle,
139	    registry: State<'_, ExportRegistry>,
140	    job_id: String,
141	    connection: ConnectionDto,
142	    chunks_json: String,
143	    processed_results_json: String,
144	    current_chunk: i32,
145	    theme: String,
146	    format: String,
147	    include_illustrations: bool,
148	    output_dir: String,
149	) -> Result<(), String> {
150	    let chunks: Vec<ChunkInput> =
151	        serde_json::from_str(&chunks_json).map_err(|e| format!("invalid chunks_json: {e}"))?;
152	    let processed: Vec<ChunkResult> =
153	        serde_json::from_str(&processed_results_json).map_err(|e| format!("invalid processed_results_json: {e}"))?;
154	
155	    let total = chunks.len() as i32;
156	    let cancel = CancellationToken::new();
157	    let cancel_clone = cancel.clone();
158	
159	    let job = ExportJob {
160	        job_id: job_id.clone(),
161	        status: "running".to_string(),
162	        progress: if total > 0 {
163	            (current_chunk * 100) / total
164	        } else {
165	            0
166	        },
167	        total_chunks: total,
168	        current_chunk,
169	        output_path: None,
170	        cancel,
171	    };
172	
173	    // Resolve output directory
174	    let resolved_output_dir = if output_dir.is_empty() {
175	        app.path()
176	            .app_data_dir()
177	            .map(|p| p.join("chronicles"))
178	            .map(|p| p.to_string_lossy().to_string())
179	            .unwrap_or_else(|_| ".".to_string())
180	    } else {
181	        output_dir
182	    };
183	
184	    registry
185	        .0
186	        .lock()
187	        .map_err(|e| e.to_string())?
188	        .insert(job_id.clone(), job);
189	
190	    let reg = Arc::clone(&registry.0);
191	    let jid = job_id.clone();
192	
193	    tokio::spawn(async move {
194	        let result = run_export_resume(
195	            &jid, &connection, &chunks, &processed, current_chunk as usize,
196	            &theme, &format, include_illustrations, &resolved_output_dir, cancel_clone, &reg,
197	        )
198	        .await;
199	
200	        let mut map = reg.lock().unwrap();
201	        if let Some(job) = map.get_mut(&jid) {
202	            match result {
203	                Ok(path) => {
204	                    job.status = "completed".to_string();
205	                    job.progress = 100;
206	                    job.output_path = Some(path);
207	                }
208	                Err(err) => {
209	                    job.status = "failed".to_string();
210	                    job.output_path = Some(err);
211	                }
212	            }
213	        }
214	    });
215	
216	    Ok(())
217	}
