261	async fn run_export(
262	    job_id: &str,
263	    connection: &ConnectionDto,
264	    chunks: &[ChunkInput],
265	    theme: &str,
266	    format: &str,
267	    _include_illustrations: bool,
268	    output_dir: &str,
269	    cancel: CancellationToken,
270	    registry: &Arc<Mutex<HashMap<String, ExportJob>>>,
271	) -> Result<String, String> {
272	    let api_key = get_api_key(&connection.id)
273	        .map_err(|e| e.to_string())?
274	        .ok_or_else(|| "Pro toto připojení není uložen žádný API klíč.".to_string())?;
275	
276	    let mut results: Vec<ChunkResult> = Vec::with_capacity(chunks.len());
277	    let total = chunks.len();
278	
279	    for (i, chunk) in chunks.iter().enumerate() {
280	        if cancel.is_cancelled() {
281	            return Err("Cancelled".to_string());
282	        }
283	
284	        let prose = process_chunk(connection, &api_key, chunk).await?;
285	        results.push(ChunkResult {
286	            index: chunk.index,
287	            prose,
288	        });
289	
290	        // Update progress in registry
291	        if let Ok(mut map) = registry.lock() {
292	            if let Some(job) = map.get_mut(job_id) {
293	                job.current_chunk = (i + 1) as i32;
294	                job.progress = if total > 0 {
295	                    ((i + 1) as i32 * 100) / total as i32
296	                } else {
297	                    0
298	                };
299	            }
300	        }
301	
302	        // Rate-limit: 4 second delay between chunks
303	        if i + 1 < total {
304	            tokio::time::sleep(tokio::time::Duration::from_secs(4)).await;
305	        }
306	    }
307	
308	    assemble_and_write(job_id, &results, theme, format, output_dir)
309	}
