311	async fn run_export_resume(
312	    job_id: &str,
313	    connection: &ConnectionDto,
314	    chunks: &[ChunkInput],
315	    processed: &[ChunkResult],
316	    start_from: usize,
317	    theme: &str,
318	    format: &str,
319	    _include_illustrations: bool,
320	    output_dir: &str,
321	    cancel: CancellationToken,
322	    registry: &Arc<Mutex<HashMap<String, ExportJob>>>,
323	) -> Result<String, String> {
324	    let api_key = get_api_key(&connection.id)
325	        .map_err(|e| e.to_string())?
326	        .ok_or_else(|| "Pro toto připojení není uložen žádný API klíč.".to_string())?;
327	
328	    let mut results: Vec<ChunkResult> = processed.to_vec();
329	    let remaining: Vec<&ChunkInput> = chunks.iter().filter(|c| c.index >= start_from).collect();
330	    let total_remaining = remaining.len();
331	
332	    for (i, chunk) in remaining.iter().enumerate() {
333	        if cancel.is_cancelled() {
334	            return Err("Cancelled".to_string());
335	        }
336	
337	        let prose = process_chunk(connection, &api_key, chunk).await?;
338	        results.push(ChunkResult {
339	            index: chunk.index,
340	            prose,
341	        });
342	
343	        // Update progress in registry
344	        if let Ok(mut map) = registry.lock() {
345	            if let Some(job) = map.get_mut(job_id) {
346	                job.current_chunk = (start_from + i + 1) as i32;
347	                job.progress = if job.total_chunks > 0 {
348	                    ((start_from + i + 1) as i32 * 100) / job.total_chunks
349	                } else {
350	                    0
351	                };
352	            }
353	        }
354	
355	        if i + 1 < total_remaining {
356	            tokio::time::sleep(tokio::time::Duration::from_secs(4)).await;
357	        }
358	    }
359	
360	    // Sort by index
361	    results.sort_by_key(|r| r.index);
362	    assemble_and_write(job_id, &results, theme, format, output_dir)
363	}
