  1	//! Sync journal I/O commands — thin Rust layer for the TS sync engine.
  2	//! The TypeScript side owns the journal format, rotation logic, and merge
  3	//! semantics; these commands are just generic filesystem primitives.
  4	
  5	use std::fs;
  6	use std::io::Write;
  7	use std::path::Path;
  8	
  9	/// Appends `line` + "\n" to `path`, creating the file (and its parent
 10	/// directories) if they don't exist yet. Returns the new file size in bytes
 11	/// (so the TS side can trigger rotation when it crosses ~10 MB).
 12	#[tauri::command]
 13	pub fn append_journal_line(path: String, line: String) -> Result<u64, String> {
 14	    let p = Path::new(&path);
 15	    if let Some(parent) = p.parent() {
 16	        fs::create_dir_all(parent)
 17	            .map_err(|e| format!("cannot create sync folder: {e}"))?;
 18	    }
 19	    let mut f = fs::OpenOptions::new()
 20	        .create(true)
 21	        .append(true)
 22	        .open(p)
 23	        .map_err(|e| format!("cannot open journal: {e}"))?;
 24	    writeln!(f, "{line}").map_err(|e| format!("cannot write journal: {e}"))?;
 25	    let meta = f.metadata().map_err(|e| format!("cannot stat journal: {e}"))?;
 26	    Ok(meta.len())
 27	}
 28	
 29	/// Lists immediate children of `dir` with `name`, `is_dir`, and `size_bytes`.
 30	/// Returns an empty array when the directory does not exist (sync disabled /
 31	/// folder not yet created) so the frontend never sees a hard error.
 32	#[tauri::command]
 33	pub fn list_sync_entries(dir: String) -> Result<Vec<SyncDirEntry>, String> {
 34	    let p = Path::new(&dir);
 35	    if !p.is_dir() {
 36	        return Ok(Vec::new());
 37	    }
 38	    let mut entries = Vec::new();
 39	    let iter = fs::read_dir(p).map_err(|e| format!("cannot read sync folder: {e}"))?;
 40	    for entry in iter {
 41	        let entry = match entry {
 42	            Ok(e) => e,
 43	            Err(_) => continue,
 44	        };
 45	        let meta = match entry.metadata() {
 46	            Ok(m) => m,
 47	            Err(_) => continue,
 48	        };
 49	        let name = entry.file_name().to_string_lossy().into_owned();
 50	        if name.starts_with('.') {
 51	            continue; // skip hidden files/folders
 52	        }
 53	        entries.push(SyncDirEntry {
 54	            name,
 55	            is_dir: meta.is_dir(),
 56	            size_bytes: meta.len(),
 57	        });
 58	    }
 59	    Ok(entries)
 60	}
 61	
 62	/// Reads up to `max_bytes` from `path` starting at `start_byte`, returning
 63	/// (raw_text, next_start_byte) where next_start_byte is the position after
 64	/// the last byte read (or `null` when EOF is reached). Used by the journal
 65	/// reader to incrementally consume large journals.
 66	#[tauri::command]
 67	pub fn read_journal_chunk(
 68	    path: String,
 69	    start_byte: u64,
 70	    max_bytes: u64,
 71	) -> Result<JournalChunk, String> {
 72	    use std::io::Read;
 73	    let mut f = fs::File::open(&path).map_err(|e| format!("cannot open journal for reading: {e}"))?;
 74	    let total = f.metadata().map_err(|e| format!("cannot stat journal: {e}"))?.len();
 75	    if start_byte >= total {
 76	        return Ok(JournalChunk {
 77	            text: String::new(),
 78	            next_start_byte: None,
 79	            total_bytes: total,
 80	        });
 81	    }
 82	    use std::io::Seek;
 83	    f.seek(std::io::SeekFrom::Start(start_byte))
 84	        .map_err(|e| format!("cannot seek journal: {e}"))?;
 85	    let limit = std::cmp::min(max_bytes as usize, (total - start_byte) as usize);
 86	    let mut buf = vec![0u8; limit];
 87	    let n = f.read(&mut buf).map_err(|e| format!("cannot read journal: {e}"))?;
 88	    buf.truncate(n);
 89	    // Extend to the next newline so we never split a line.
 90	    if (start_byte + n as u64) < total {
 91	        let mut extra = Vec::new();
 92	        let mut byte_buf = [0u8; 1];
 93	        loop {
 94	            match f.read(&mut byte_buf) {
 95	                Ok(0) => break,
 96	                Ok(1) => {
 97	                    extra.push(byte_buf[0]);
 98	                    if byte_buf[0] == b'\n' {
 99	                        break;
100	                    }
101	                }
102	                Ok(_) => break, // buffer is 1 byte, only 0/1 possible
103	                Err(_) => break,
104	            }
105	        }
106	        buf.extend(&extra);
107	    }
108	    let text = String::from_utf8_lossy(&buf).into_owned();
109	    let end = start_byte + buf.len() as u64;
110	    Ok(JournalChunk {
111	        text,
112	        next_start_byte: if end < total { Some(end) } else { None },
113	        total_bytes: total,
114	    })
115	}
