117	/// Deletes a file — used by the journal reader to clean up fully-processed
118	/// rotated journals after they've been consumed.
119	#[tauri::command]
120	pub fn delete_sync_file(path: String) -> Result<(), String> {
121	    match fs::remove_file(&path) {
122	        Ok(()) => Ok(()),
123	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
124	        Err(e) => Err(format!("cannot delete sync file: {e}")),
125	    }
126	}
