import { useEffect } from "react";

/**
 * Android back button handler for Tauri 2 mobile.
 *
 * On Android, the system back button (or gesture) should:
 *  1. Close any open panel (Memory, Inventory, Quests, Director, Group, Export)
 *  2. If no panel is open, navigate back in browser history (to chat list)
 *
 * Desktop builds are a no-op — there is no back button to intercept.
 */

export interface BackButtonState {
  /** Whether any side panel is currently open. */
  hasOpenPanel: boolean;
}

/**
 * Register a handler for the Android back button.
 *
 * @param state  — current panel open state
 * @param onBack — called when the back button should close panels or navigate back
 */
export function useAndroidBack(
  state: BackButtonState,
  onBack: () => void,
) {
  useEffect(() => {
    // Only active on Android WebView
    if (typeof window === "undefined") return;

    // Tauri 2 mobile fires a custom event when the back button is pressed.
    // The exact event name depends on the Tauri version; we listen for both
    // the Tauri 2 convention and the Capacitor fallback.
    const handler = (e: Event) => {
      e.preventDefault();
      onBack();
    };

    // Tauri 2 mobile back button event (v2 convention)
    window.addEventListener("tauri://back", handler);
    // Some Tauri 2 builds use this variant
    window.addEventListener("android-back", handler);

    // Also intercept the hardware back button via the History API —
    // when a panel is open, pushing a dummy state lets us catch
    // the back navigation before it leaves the app.
    if (state.hasOpenPanel) {
      window.history.pushState({ panel: true }, "");
    }

    const popstateHandler = () => {
      if (state.hasOpenPanel) {
        // Push another state to keep us on this page
        window.history.pushState({ panel: true }, "");
        onBack();
      }
    };
    window.addEventListener("popstate", popstateHandler);

    return () => {
      window.removeEventListener("tauri://back", handler);
      window.removeEventListener("android-back", handler);
      window.removeEventListener("popstate", popstateHandler);
    };
  }, [state.hasOpenPanel, onBack]);
}

import { useEffect } from "react";
import { HashRouter, Navigate, Route, Routes } from "react-router-dom";

import { getAutoBackupEnabled, getAutoBackupMaxCount, runAutoBackup } from "./db/backup";
import { runSyncOnStartup } from "./db/syncReader";
import { useSettingsStore } from "./stores/settingsStore";
import { CardEditor } from "./ui/characters/CardEditor";
import { GalleryScreen } from "./ui/characters/GalleryScreen";
import { ChatListScreen } from "./ui/chat/ChatListScreen";
import { ChatScreen } from "./ui/chat/ChatScreen";
import { SamplerToast } from "./ui/common/SamplerToast";
import { UndoToast } from "./ui/common/UndoToast";
import { AppShell } from "./ui/layout/AppShell";
import { LorebookEditor } from "./ui/lorebooks/LorebookEditor";
import { LorebooksListScreen } from "./ui/lorebooks/LorebooksListScreen";
import { PersonasScreen } from "./ui/personas/PersonasScreen";
import { SettingsScreen } from "./ui/settings/SettingsScreen";
import { UpdateBanner } from "./ui/UpdateBanner";
import { KeyboardShortcutListener } from "./ui/useKeyboardShortcuts";

function App() {
  const { hydrated, hydrate } = useSettingsStore();

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  // Startup auto-backup (M14.1) — driven from the frontend so it can respect
  // the settings stored in SQLite and checkpoint the WAL before zipping.
  useEffect(() => {
    void (async () => {
      try {
        if (await getAutoBackupEnabled()) {
          await runAutoBackup(await getAutoBackupMaxCount());
        }
      } catch (err) {
        console.warn("startup auto-backup failed:", err);
      }
    })();
  }, []);

  // Startup sync (M14) — scan and apply foreign device journals after DB is ready.
  useEffect(() => {
    if (!hydrated) return;
    void (async () => {
      try {
        await runSyncOnStartup();
      } catch (err) {
        console.warn("[sync] startup sync failed:", err);
      }
    })();
  }, [hydrated]);

  if (!hydrated) {
    return null;
  }

  return (
    <HashRouter>
      <AppShell>
        <Routes>
          <Route path="/" element={<ChatListScreen />} />
          <Route path="/chat/:id" element={<ChatScreen />} />
          <Route path="/characters" element={<GalleryScreen />} />
          <Route path="/characters/:id" element={<CardEditor />} />
          <Route path="/personas" element={<PersonasScreen />} />
          <Route path="/lorebooks" element={<LorebooksListScreen />} />
          <Route path="/lorebooks/:id" element={<LorebookEditor />} />
          <Route path="/settings" element={<SettingsScreen />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
        <KeyboardShortcutListener />
        <UpdateBanner />
        <SamplerToast />
        <UndoToast />
      </AppShell>
    </HashRouter>
  );
}

export default App;

