// Error log collection (roadmap M11 §3, tiered logging follow-up): wraps
// console.debug/info/warn/error and catches uncaught window errors /
// unhandled promise rejections, forwarding each one to the Rust
// `append_log` command so it lands in `$APPDATA/logs/app.log`. Users can
// then attach that file when reporting a bug instead of having to
// reproduce it in front of a developer.
//
// The console passthrough always happens regardless of the configured
// level (DevTools shows everything); the configured minimum level (see
// `refreshLogLevel`/`getLogLevel`/`setLogLevel` below) only gates whether a
// given call also gets forwarded to the file.
//
// This is best-effort telemetry, not a critical path: every write is
// fire-and-forget (no await, errors swallowed) so a broken log pipe can
// never itself cause a visible failure, and several guards keep it from
// spamming the log file or recursing into itself.

import { invoke } from "@tauri-apps/api/core";
import { getLogLevel as getStoredLogLevel, setLogLevel as setStoredLogLevel, type LogLevel } from "./db/repositories/settingsRepo";

const DEDUPE_WINDOW_MS = 5000;
const MAX_WRITES_PER_MINUTE = 20;
const RATE_WINDOW_MS = 60_000;
const MAX_MESSAGE_LEN = 2000;

// Ascending severity. The configured minimum level gates which lines get
// forwarded to `append_log`/app.log — the console passthrough happens
// unconditionally regardless of this cache, so DevTools always shows
// everything.
const LEVEL_RANK: Record<LogLevel, number> = { debug: 0, info: 1, warn: 2, error: 3 };
const DEFAULT_LOG_LEVEL: LogLevel = "info";

// In-memory cache of the configured minimum level, so we don't hit the DB
// on every single log call. Populated by `refreshLogLevel()`, which should
// be called once at startup and again whenever the level is changed via
// Settings.
let cachedLogLevel: LogLevel = DEFAULT_LOG_LEVEL;

/** Re-reads the configured log level from settings and updates the
 *  in-memory cache used to gate file writes. Call once at startup
 *  (alongside `initErrorLogging()`) and again whenever the level is
 *  changed via the Settings UI so the change takes effect immediately. */
export async function refreshLogLevel(): Promise<void> {
  try {
    const level = await getStoredLogLevel();
    cachedLogLevel = level ?? DEFAULT_LOG_LEVEL;
  } catch {
    // Best-effort: keep whatever was cached before (or the default) if the
    // setting can't be read.
  }
}

/** Reads the current in-memory cached log level (does not hit the DB). */
export function getLogLevel(): LogLevel {
  return cachedLogLevel;
}

/** Persists a new minimum log level and immediately refreshes the
 *  in-memory cache so the change takes effect without a restart. */
export async function setLogLevel(level: LogLevel): Promise<void> {
  await setStoredLogLevel(level);
  await refreshLogLevel();
}

let installed = false;
// Recursion guard: set for the duration of a single append_log call so an
// error thrown while logging (e.g. from JSON.stringify or invoke itself)
// never triggers another log write.
let logging = false;

// message -> last-logged timestamp, for the 1-per-5s dedupe.
const lastSeen = new Map<string, number>();
// Timestamps (ms) of writes within the current rate-limit window.
let writeTimestamps: number[] = [];

function serializeArg(arg: unknown): string {
  if (arg instanceof Error) {
    const stackLines = (arg.stack ?? "").split("\n").slice(0, 3).join("\n");
    return `${arg.message}${stackLines ? `\n${stackLines}` : ""}`;
  }
  if (typeof arg === "string") return arg;
  try {
    return JSON.stringify(arg);
  } catch {
    return String(arg);
  }
}

/** Direct write to app.log bypassing dedup/rate-limit — for one-shot
 *  diagnostic records (e.g. sampler-param warnings). */
export function appendLog(line: string): void {
  void invoke("append_log", { line }).catch(() => {});
}

function buildLine(level: string, args: unknown[]): string {
  const message = args.map(serializeArg).join(" ").slice(0, MAX_MESSAGE_LEN);
  return `${new Date().toISOString()} [${level}] ${message}`;
}

function shouldSkip(dedupeKey: string): boolean {
  const now = Date.now();

  const last = lastSeen.get(dedupeKey);
  if (last !== undefined && now - last < DEDUPE_WINDOW_MS) {
    return true;
  }
  lastSeen.set(dedupeKey, now);

  writeTimestamps = writeTimestamps.filter((ts) => now - ts < RATE_WINDOW_MS);
  if (writeTimestamps.length >= MAX_WRITES_PER_MINUTE) {
    return true;
  }
  writeTimestamps.push(now);
  return false;
}

function logLine(level: LogLevel, line: string) {
  if (logging) return; // recursion guard
  if (LEVEL_RANK[level] < LEVEL_RANK[cachedLogLevel]) return; // below configured threshold
  if (shouldSkip(line)) return;

  logging = true;
  try {
    // Fire-and-forget: never await, never let a rejection surface.
    void invoke("append_log", { line }).catch(() => {});
  } catch {
    // Swallow synchronous throws too (e.g. invoke not available outside Tauri).
  } finally {
    logging = false;
  }
}

/**
 * Installs the console/window hooks. Idempotent — safe to call more than
 * once (e.g. in tests or HMR) without double-wrapping console methods.
 */
export function initErrorLogging(): void {
  if (installed) return;
  installed = true;

  const originalError = console.error.bind(console);
  const originalWarn = console.warn.bind(console);
  const originalInfo = console.info.bind(console);
  const originalDebug = console.debug.bind(console);

  console.error = (...args: unknown[]) => {
    originalError(...args);
    logLine("error", buildLine("error", args));
  };

  console.warn = (...args: unknown[]) => {
    originalWarn(...args);
    logLine("warn", buildLine("warn", args));
  };

  // console.info is for deliberate, low-volume diagnostic breadcrumbs a
  // user might want to review later (e.g. the function-calling prototype's
  // round-trip log) — unlike error/warn it's opt-in per call site, so it's
  // wrapped the same way but expected to be used sparingly.
  console.info = (...args: unknown[]) => {
    originalInfo(...args);
    logLine("info", buildLine("info", args));
  };

  // console.debug is for verbose, only-useful-when-actively-debugging
  // breadcrumbs — gated out of app.log by default (min level "info") but
  // always visible in DevTools like the others.
  console.debug = (...args: unknown[]) => {
    originalDebug(...args);
    logLine("debug", buildLine("debug", args));
  };

  window.addEventListener("error", (event: ErrorEvent) => {
    const arg = event.error instanceof Error ? event.error : event.message;
    logLine("error", buildLine("error", [arg]));
  });

  window.addEventListener("unhandledrejection", (event: PromiseRejectionEvent) => {
    logLine("error", buildLine("error", [event.reason]));
  });
}

import type { Character } from "../db/repositories/charactersRepo";
import type { ChatMember } from "../db/repositories/chatMembersRepo";
import type { Chat } from "../db/repositories/chatsRepo";
import type { Message } from "../db/repositories/messagesRepo";
import type { ChatStreamHandle } from "../providers/chatStream";
import type { PromptReport } from "../prompt/promptBuilder";
import type { GameOverState } from "../chat/gameOver";

export interface ChatState {
  chatId: string | null;
  /** The chat row itself, loaded by `openChat` — components used to load
   * this on their own; the store now owns it so speaker resolution has
   * fresh-enough data without a round trip per action (plan §5). */
  chat: Chat | null;
  /** Roster (`chat_members`), ordered by position — the source of truth
   * for who's in the chat. */
  members: ChatMember[];
  /** Character cards for `members`, in the same order; entries whose card
   * failed to load are skipped. */
  memberCharacters: Character[];
  /** Manually-picked speaker for the next `sendMessage`/used by
   * `suggestReplies` — ignored while `autoReply` is on. */
  selectedSpeakerId: string | null;
  /** Automatic speaker selection (mirrors `chat.autoReply`, kept in sync by
   * `setAutoReplyMode`). */
  autoReply: boolean;
  /** Which member is currently streaming a reply — drives the streaming
   * bubble's avatar/name in group chats. Set at the start of every stream,
   * cleared once `finalize` has persisted the message. */
  streamingSpeakerId: string | null;
  messages: Message[];
  loading: boolean;
  streaming: boolean;
  /** Set while regenerating an existing assistant message; null while
   * streaming a brand new message. */
  streamingMessageId: string | null;
  streamingText: string;
  error: string | null;
  /** Whether `error` came from a retryable failure (429/5xx from the
   * provider, or the app being offline) — drives the "Try again" button in
   * the chat error banner (plan §9). */
  errorRetryable: boolean;
  /** Re-runs whatever request just failed, when `errorRetryable` is true. */
  retry: (() => void) | null;
  handle: ChatStreamHandle | null;
  pendingFinalize: ((content: string) => Promise<void>) | null;
  /** Ids of assistant messages whose stored content is a partial response
   * (stream was aborted or errored mid-way) — surfaces a "continue" action
   * in the UI instead of silently presenting a truncated reply as final
   * (plan §9). Cleared once the message is edited, regenerated, or
   * continued. Session-only (not persisted), since it only matters for the
   * chat currently open. */
  interruptedMessageIds: Set<string>;
  /** Report from the last PromptBuilder call for this chat — what exactly
   * went to the model, token counts, what got trimmed. Shown in the memory
   * panel's "Prompt" tab (plan §7 M5). Null until a message has been sent
   * (or if the character couldn't be loaded). */
  lastPromptReport: PromptReport | null;
  /** Whether there are older messages in the DB beyond what's currently
   * loaded — drives MessageList's "load older" affordance for long chats
   * (plan §9: paginate, load last 100, scroll-up fetches more). */
  hasOlderMessages: boolean;
  loadingOlderMessages: boolean;
  /** On-demand reply suggestions ("what could {{user}} do next") — filled by
   * `suggestReplies`, cleared when a message is sent or the chat changes.
   * Opt-in per press so it never burns tokens unasked (plan follow-up). */
  suggestions: string[] | null;
  suggesting: boolean;
  /** Hardcore-mode game over state for this chat — null unless the model
   *  emitted [GAMEOVER:reason] while chat.hardcoreMode was on. Loaded by
   *  `openChat` and refreshed after every stream; once set, `sendMessage`/
   *  `triggerSpeaker`/`regenerate`/`continueMessage` all refuse to run. */
  gameOver: GameOverState | null;
  /** Skill named by the GM's last [CHECK:skill name] tag — offered to the
   *  quick-roll button as its bonus source (see pendingCheck.ts). Loaded by
   *  `openChat`/refreshed after every stream, cleared on the next
   *  `sendMessage` regardless of whether it was used. */
  pendingCheckSkill: string | null;

  openChat: (chatId: string) => Promise<void>;
  closeChat: () => Promise<void>;
  loadOlderMessages: () => Promise<void>;
  sendMessage: (content: string) => Promise<void>;
  /** Group chats: makes `speakerId` reply without a new player message —
   * "reply now" (plan §5/§7). */
  triggerSpeaker: (speakerId: string) => Promise<void>;
  regenerate: (messageId: string) => Promise<void>;
  continueMessage: (messageId: string) => Promise<void>;
  editMessage: (messageId: string, content: string) => Promise<void>;
  switchSwipe: (messageId: string, offset: number) => Promise<void>;
  stop: () => Promise<void>;
  dismissError: () => void;
  suggestReplies: () => Promise<void>;
  clearSuggestions: () => void;
  /** Adds a character to the roster (converts a solo chat into a group the
   * first time it's called) and reloads `members`/`memberCharacters`. */
  addMember: (characterId: string) => Promise<void>;
  /** Removes a member; refuses (returns `false`) to empty the roster. When
   * removing the current primary member, promotes the next member first so
   * the chat always has a valid `chats.character_id`. */
  removeMember: (characterId: string) => Promise<boolean>;
  setAutoReplyMode: (on: boolean) => Promise<void>;
  setHardcoreMode: (on: boolean) => Promise<void>;
  setSelectedSpeaker: (id: string) => void;
}

export type Setter = (
  partial:
    | Partial<ChatState>
    | ((state: ChatState) => Partial<ChatState>),
) => void;

export type Getter = () => ChatState;

