const DEFAULT_LOG_LEVEL: LogLevel = "info";

// In-memory cache of the configured minimum level, so we don't hit the DB
// on every single log call. Populated by `refreshLogLevel()`, which should
// be called once at startup and again whenever the level is changed via
// Settings.
let cachedLogLevel: LogLevel = DEFAULT_LOG_LEVEL;

/** Re-reads the configured log level from settings and updates the
 *  in-memory cache used to gate file writes. Call once at startup
 *  (alongside `initErrorLogging()`) and again whenever the level is
 *  changed via the Settings UI so the change takes effect immediately. */
export async function refreshLogLevel(): Promise<void> {
  try {
    const level = await getStoredLogLevel();
    cachedLogLevel = level ?? DEFAULT_LOG_LEVEL;
  } catch {
    // Best-effort: keep whatever was cached before (or the default) if the
    // setting can't be read.
  }
}

/** Reads the current in-memory cached log level (does not hit the DB). */
export function getLogLevel(): LogLevel {
  return cachedLogLevel;
}

/** Persists a new minimum log level and immediately refreshes the
 *  in-memory cache so the change takes effect without a restart. */
export async function setLogLevel(level: LogLevel): Promise<void> {
  await setStoredLogLevel(level);
  await refreshLogLevel();
}

let installed = false;
// Recursion guard: set for the duration of a single append_log call so an
// error thrown while logging (e.g. from JSON.stringify or invoke itself)
// never triggers another log write.
let logging = false;

// message -> last-logged timestamp, for the 1-per-5s dedupe.
const lastSeen = new Map<string, number>();
// Timestamps (ms) of writes within the current rate-limit window.
let writeTimestamps: number[] = [];

function serializeArg(arg: unknown): string {
  if (arg instanceof Error) {
    const stackLines = (arg.stack ?? "").split("\n").slice(0, 3).join("\n");
    return `${arg.message}${stackLines ? `\n${stackLines}` : ""}`;
  }
  if (typeof arg === "string") return arg;
  try {
    return JSON.stringify(arg);
  } catch {
    return String(arg);
  }
}

/** Direct write to app.log bypassing dedup/rate-limit — for one-shot
 *  diagnostic records (e.g. sampler-param warnings). */
export function appendLog(line: string): void {
  void invoke("append_log", { line }).catch(() => {});
}

function buildLine(level: string, args: unknown[]): string {
  const message = args.map(serializeArg).join(" ").slice(0, MAX_MESSAGE_LEN);
  return `${new Date().toISOString()} [${level}] ${message}`;
}

function shouldSkip(dedupeKey: string): boolean {
  const now = Date.now();

  const last = lastSeen.get(dedupeKey);
  if (last !== undefined && now - last < DEDUPE_WINDOW_MS) {
    return true;
  }
  lastSeen.set(dedupeKey, now);

  writeTimestamps = writeTimestamps.filter((ts) => now - ts < RATE_WINDOW_MS);
  if (writeTimestamps.length >= MAX_WRITES_PER_MINUTE) {
    return true;
  }
  writeTimestamps.push(now);
  return false;
}

function logLine(level: LogLevel, line: string) {
  if (logging) return; // recursion guard
  if (LEVEL_RANK[level] < LEVEL_RANK[cachedLogLevel]) return; // below configured threshold
  if (shouldSkip(line)) return;

  logging = true;
  try {
    // Fire-and-forget: never await, never let a rejection surface.
    void invoke("append_log", { line }).catch(() => {});
  } catch {
    // Swallow synchronous throws too (e.g. invoke not available outside Tauri).
  } finally {
    logging = false;
  }
}

/**
 * Installs the console/window hooks. Idempotent — safe to call more than
 * once (e.g. in tests or HMR) without double-wrapping console methods.
 */
export function initErrorLogging(): void {
  if (installed) return;
  installed = true;

  const originalError = console.error.bind(console);
  const originalWarn = console.warn.bind(console);
  const originalInfo = console.info.bind(console);
  const originalDebug = console.debug.bind(console);

  console.error = (...args: unknown[]) => {
    originalError(...args);
    logLine("error", buildLine("error", args));
  };

  console.warn = (...args: unknown[]) => {
    originalWarn(...args);
    logLine("warn", buildLine("warn", args));
  };

  // console.info is for deliberate, low-volume diagnostic breadcrumbs a
  // user might want to review later (e.g. the function-calling prototype's
  // round-trip log) — unlike error/warn it's opt-in per call site, so it's
  // wrapped the same way but expected to be used sparingly.
  console.info = (...args: unknown[]) => {
    originalInfo(...args);
    logLine("info", buildLine("info", args));
  };

  // console.debug is for verbose, only-useful-when-actively-debugging
  // breadcrumbs — gated out of app.log by default (min level "info") but
  // always visible in DevTools like the others.
  console.debug = (...args: unknown[]) => {
    originalDebug(...args);
    logLine("debug", buildLine("debug", args));
  };

  window.addEventListener("error", (event: ErrorEvent) => {
    const arg = event.error instanceof Error ? event.error : event.message;
    logLine("error", buildLine("error", [arg]));
  });

  window.addEventListener("unhandledrejection", (event: PromiseRejectionEvent) => {
    logLine("error", buildLine("error", [event.reason]));
  });
}

import { create } from "zustand";
import { invoke } from "@tauri-apps/api/core";

import {
  createChat,
  deleteChat,
  listChats,
  renameChat,
  setChatConnection,
  setChatEmbeddingConnection,
  setChatImageConnection,
  setChatPersona,
  setChatPreset,
  setExtractionConnection,
  setTagExtractionConnection,
  type Chat,
  type ChatDraft,
} from "../db/repositories/chatsRepo";
import { createCalendarEvent } from "../db/repositories/calendarEventsRepo";
import { setCalendarSetting } from "../db/repositories/settingsRepo";
import { generateCalendarEvents } from "../memory/calendarEvents";
import { calendarToJSON, defaultCalendarDate } from "../memory/calendar";

interface ChatListState {
  chats: Chat[];
  loaded: boolean;
  load: () => Promise<void>;
  create: (draft: ChatDraft) => Promise<Chat>;
  rename: (id: string, title: string) => Promise<void>;
  setConnection: (id: string, connectionId: string | null) => Promise<void>;
  setPersona: (id: string, personaId: string | null) => Promise<void>;
  setPreset: (id: string, presetId: string | null) => Promise<void>;
  setExtractionConnection: (id: string, connectionId: string | null) => Promise<void>;
  setTagExtractionConnection: (id: string, connectionId: string | null) => Promise<void>;
  setEmbeddingConnection: (id: string, connectionId: string | null) => Promise<void>;
  setImageConnection: (id: string, connectionId: string | null) => Promise<void>;
  remove: (id: string) => Promise<void>;
}

export const useChatListStore = create<ChatListState>((set, get) => ({
  chats: [],
  loaded: false,

  load: async () => {
    const chats = await listChats();
    set({ chats, loaded: true });
  },

  create: async (draft) => {
    const created = await createChat(draft);
    set({ chats: [created, ...get().chats] });
    // Initialize calendar date + seed events (fire-and-forget, no AI)
    void (async () => {
      try {
        const cal = defaultCalendarDate();
        await setCalendarSetting(created.id, calendarToJSON(cal));
        const events = generateCalendarEvents(created.id, cal.year);
        for (const ev of events) {
          await createCalendarEvent(ev);
        }
      } catch (err) {
        console.warn("chatListStore: failed to init calendar", err);
      }
    })();
    return created;
  },

  rename: async (id, title) => {
    await renameChat(id, title);
    set({ chats: get().chats.map((c) => (c.id === id ? { ...c, title } : c)) });
  },

  setConnection: async (id, connectionId) => {
    await setChatConnection(id, connectionId);
    set({ chats: get().chats.map((c) => (c.id === id ? { ...c, connectionId } : c)) });
  },

  setPersona: async (id, personaId) => {
    await setChatPersona(id, personaId);
    set({ chats: get().chats.map((c) => (c.id === id ? { ...c, personaId } : c)) });
  },

  setPreset: async (id, presetId) => {
    await setChatPreset(id, presetId);
    set({ chats: get().chats.map((c) => (c.id === id ? { ...c, presetId } : c)) });
  },

  setExtractionConnection: async (id, connectionId) => {
    await setExtractionConnection(id, connectionId);
    set({
      chats: get().chats.map((c) => (c.id === id ? { ...c, extractionConnectionId: connectionId } : c)),
    });
  },

  setTagExtractionConnection: async (id, connectionId) => {
    await setTagExtractionConnection(id, connectionId);
    set({
      chats: get().chats.map((c) => (c.id === id ? { ...c, tagExtractionConnectionId: connectionId } : c)),
    });
  },

  setEmbeddingConnection: async (id, connectionId) => {
    await setChatEmbeddingConnection(id, connectionId);
    set({
      chats: get().chats.map((c) => (c.id === id ? { ...c, embeddingConnectionId: connectionId } : c)),
    });
  },

  setImageConnection: async (id, connectionId) => {
    await setChatImageConnection(id, connectionId);
    set({
      chats: get().chats.map((c) => (c.id === id ? { ...c, imageConnectionId: connectionId } : c)),
    });
  },

  remove: async (id) => {
    await deleteChat(id);
    // Fire-and-forget: also delete the per-chat log file so it doesn't
    // accumulate orphaned logs from deleted/test chats.
    void invoke("delete_chat_log", { chatId: id }).catch(() => {});
    set({ chats: get().chats.filter((c) => c.id !== id) });
  },
}));

use std::fs;
use std::io::Write;
use std::path::PathBuf;

use tauri::{AppHandle, Manager};

use crate::commands::secrets::get_api_key;
use crate::providers::{self, ChatMessage, ConnectionDto, Role};

const EXTRACTION_SYSTEM_PROMPT: &str = r#"You are a game state extractor for an RPG. Read the narrator's response below and extract any game-mechanical changes into a single JSON object.

Return ONLY the JSON object, no other text, no markdown fences. The JSON must use this schema:

{
  "time_elapsed_minutes": number | null,
  "inventory": [{"op": "add" | "remove", "item": "string", "qty": number}],
  "skills": [{"name": "string", "delta": number}],
  "levels": {"xp_delta": number, "level_delta": number},
  "conditions": [{"op": "add" | "remove", "name": "string", "description": "string | null", "duration": "string | null"}],
  "modifications": [{"op": "add" | "remove", "name": "string"}],
  "factions": [{"name": "string", "delta": number}],
  "crafting": [{"result_item": "string", "ingredients": ["string"]}],
  "crafted": [{"result_item": "string", "perks": ["string"]}],
  "quests": [{"op": "start" | "complete" | "fail" | "note", "name": "string", "note": "string | null"}],
  "game_over": "string | null",
  "check_skill": "string | null",
  "relevant_context": {
    "skills": ["string"],
    "item_keywords": ["string"],
    "recipe_keywords": ["string"]
  }
}

Rules:
- If nothing changed in a category, use an empty array or null.
- time_elapsed_minutes: how many minutes passed in the story (e.g. "two hours later" = 120). If unclear, use null.
- inventory: items gained, lost, or whose qty changed. "He found a sword" = add sword qty 1. "He dropped his shield" = remove shield qty 1.
- skills: new skills learned or existing ones improved. Delta is the change (positive = improved, negative = worsened).
- levels: xp_delta is XP change, level_delta is level change.
- conditions: temporary effects like "exhausted", "injured", "blessed".
- modifications: permanent body changes like "scar on cheek", "tattoo".
- factions: reputation changes with named groups.
- crafting: new recipes discovered (result_item + ingredients).
- crafted: items successfully crafted (result_item + perks).
- quests: new quests started, completed, failed, or noted.
- game_over: if the character died, state the reason. Otherwise null.
- check_skill: if a skill check was called, name the skill. Otherwise null.
- relevant_context: helps filter what skills/items/recipes to show the storyteller in the next turn. Look at the current scene and list:
  - skills: name any character skills the scene suggests could be useful (e.g. a river suggests Swimming, a locked door suggests Lockpicking). Include skills that ARE ALREADY KNOWN by the character. Empty array if no skills stand out.
  - item_keywords: keywords from the scene that suggest what items might be needed (e.g. "river" → "voda", "rope", "boat"). These help surface relevant inventory items.
  - recipe_keywords: keywords from materials or crafting opportunities in the scene (e.g. "iron ore" → "železo", "ruda"). These help surface relevant crafting recipes.

IMPORTANT: Only extract changes that are explicitly described in the text. Do not invent or hallucinate. If the text just describes scenery or dialogue with no mechanical changes, return empty arrays."#;

fn extractor_log_path(app: &AppHandle) -> Result<PathBuf, String> {
    let dir = app
        .path()
        .app_data_dir()
        .map_err(|e| format!("nepodařilo se najít adresář aplikace: {e}"))?
        .join("logs");
    fs::create_dir_all(&dir).map_err(|e| format!("nepodařilo se vytvořit adresář logů: {e}"))?;
    Ok(dir.join("extractor.log"))
}

fn append_extractor_log(app: &AppHandle, line: &str) {
    let Ok(path) = extractor_log_path(app) else { return };
    let mut file = match fs::OpenOptions::new().create(true).append(true).open(&path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let _ = writeln!(file, "{line}");
}

fn chrono_now() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let dur = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = dur.as_secs();
    let millis = dur.subsec_millis();
    let days_since_epoch = secs / 86400;
    let time_of_day = secs % 86400;
    let hours = time_of_day / 3600;
    let minutes = (time_of_day % 3600) / 60;
    let secs_rem = time_of_day % 60;
    let total_days = days_since_epoch as i64;
    let z = total_days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u32;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if m <= 2 { y + 1 } else { y };
    format!("{year:04}-{m:02}-{d:02}T{hours:02}:{minutes:02}:{secs_rem:02}.{millis:03}Z")
}

/// Sends the narrator's response to a tag-extraction model (typically a
/// fast/free model like Gemini Flash) and returns the model's JSON output.
/// Also writes a detailed debug log to `extractor.log` in the app data
/// directory so the user can inspect extraction I/O in real time.
#[tauri::command]
pub async fn extract_game_tags(
    app: AppHandle,
    connection: ConnectionDto,
    response_text: String,
    state_context: Option<String>,
) -> Result<String, String> {
    let ts = chrono_now();

    // Build the user message: state context (if any) + narrator response.
    let user_message = match state_context {
        Some(ref ctx) if !ctx.is_empty() => format!("{ctx}\n\n---\n\n{response_text}"),
        _ => response_text.clone(),
    };

    // Log input (truncated)
    let input_preview: String = response_text.chars().take(500).collect();
    append_extractor_log(
        &app,
        &format!(
            "══════ EXTRACT {ts} IN ({}/{}) ══════\n{input_preview}…",
            connection.provider, connection.model
        ),
    );

    let api_key = get_api_key(&connection.id)
        .map_err(|e| e.to_string())?
        .ok_or_else(|| "Pro toto připojení není uložen žádný API klíč.".to_string())?;

    let messages = vec![
        ChatMessage {
            role: Role::System,
            content: EXTRACTION_SYSTEM_PROMPT.into(),
            function_call: None,
            function_response: None,
        },
        ChatMessage {
            role: Role::User,
            content: user_message,
            function_call: None,
            function_response: None,
        },
    ];

    let raw = providers::complete(&connection, &api_key, &messages)
        .await
        .map_err(|e| {
            append_extractor_log(&app, &format!("ERROR: {e}"));
            e.to_string()
        })?;

    // Log output (truncated)
    let output_preview: String = raw.chars().take(800).collect();
    append_extractor_log(
        &app,
        &format!("══════ RESULT {ts} ══════\n{output_preview}"),
    );

    // Strip markdown fences
    let trimmed = raw.trim();
    if trimmed.starts_with("```") {
        let inner = trimmed
            .strip_prefix("```json")
            .or_else(|| trimmed.strip_prefix("```"))
            .unwrap_or(trimmed);
        let cleaned = inner.strip_suffix("```").unwrap_or(inner);
        Ok(cleaned.trim().to_string())
    } else {
        Ok(trimmed.to_string())
    }
}

import { create } from "zustand";

import {
  createConnection,
  deleteConnection,
  listConnections,
  updateConnection,
} from "../db/repositories/connectionsRepo";
import type { ConnectionConfig, ConnectionDraft } from "../providers/types";

interface ConnectionsState {
  connections: ConnectionConfig[];
  loaded: boolean;
  load: () => Promise<void>;
  add: (draft: ConnectionDraft) => Promise<ConnectionConfig>;
  update: (id: string, draft: ConnectionDraft) => Promise<ConnectionConfig>;
  remove: (id: string) => Promise<void>;
}

export const useConnectionsStore = create<ConnectionsState>((set, get) => ({
  connections: [],
  loaded: false,

  load: async () => {
    const connections = await listConnections();
    set({ connections, loaded: true });
  },

  add: async (draft) => {
    const created = await createConnection(draft);
    set({ connections: [...get().connections, created] });
    return created;
  },

  update: async (id, draft) => {
    const updated = await updateConnection(id, draft);
    set({
      connections: get().connections.map((c) => (c.id === id ? updated : c)),
    });
    return updated;
  },

  remove: async (id) => {
    await deleteConnection(id);
    set({ connections: get().connections.filter((c) => c.id !== id) });
  },
}));

import { create } from "zustand";

import i18n, { type SupportedLanguage } from "../i18n";
import { getSetting, setSetting } from "../db/repositories/settingsRepo";
import type { CalendarMode } from "../memory/calendar";

export type Theme = "dark" | "light";

/** Root font-size scale in % — everything is sized in rem, so this scales
 * the whole UI. Keep the steps modest so layouts don't break. */
export const FONT_SCALES = [87.5, 100, 112.5, 125, 150, 175, 200] as const;
export type FontScale = (typeof FONT_SCALES)[number];
const DEFAULT_FONT_SCALE: FontScale = 100;

interface SettingsState {
  theme: Theme;
  language: SupportedLanguage;
  fontScale: FontScale;
  calendarMode: CalendarMode;
  hydrated: boolean;
  hydrate: () => Promise<void>;
  setTheme: (theme: Theme) => Promise<void>;
  setLanguage: (language: SupportedLanguage) => Promise<void>;
  setFontScale: (scale: FontScale) => Promise<void>;
  setCalendarMode: (mode: CalendarMode) => Promise<void>;
}

function applyTheme(theme: Theme) {
  if (typeof document === "undefined") return;
  const root = document.documentElement;
  root.classList.remove("dark", "light");
  root.classList.add(theme);
}

function applyFontScale(scale: FontScale) {
  if (typeof document === "undefined") return;
  document.documentElement.style.fontSize = scale === 100 ? "" : `${scale}%`;
}

function parseFontScale(raw: string | null): FontScale {
  const value = Number(raw);
  return (FONT_SCALES as readonly number[]).includes(value)
    ? (value as FontScale)
    : DEFAULT_FONT_SCALE;
}

export const useSettingsStore = create<SettingsState>((set) => ({
  theme: "dark",
  language: "cs",
  fontScale: DEFAULT_FONT_SCALE,
  calendarMode: "fantasy",
  hydrated: false,

  hydrate: async () => {
    const [storedTheme, storedLanguage, storedFontScale, storedCalendarMode] = await Promise.all([
      getSetting("theme"),
      getSetting("language"),
      getSetting("font_scale"),
      getSetting("calendar_mode"),
    ]);
    const theme: Theme = storedTheme === "light" ? "light" : "dark";
    const language: SupportedLanguage = storedLanguage === "en" ? "en" : "cs";
    const fontScale = parseFontScale(storedFontScale);
    const calendarMode: CalendarMode = storedCalendarMode === "real" ? "real" : "fantasy";

    applyTheme(theme);
    applyFontScale(fontScale);
    await i18n.changeLanguage(language);

    set({ theme, language, fontScale, calendarMode, hydrated: true });
  },

  setTheme: async (theme) => {
    applyTheme(theme);
    set({ theme });
    await setSetting("theme", theme);
  },

  setLanguage: async (language) => {
    await i18n.changeLanguage(language);
    set({ language });
    await setSetting("language", language);
  },

  setFontScale: async (fontScale) => {
    applyFontScale(fontScale);
    set({ fontScale });
    await setSetting("font_scale", String(fontScale));
  },

  setCalendarMode: async (calendarMode) => {
    set({ calendarMode });
    await setSetting("calendar_mode", calendarMode);
  },
}));

// Apply a sane default immediately so the very first paint (before the DB
// hydration resolves) is already dark-themed, per the "dark by default"
// requirement.
applyTheme(useSettingsStore.getState().theme);

import { getCharacter, type Character } from "../db/repositories/charactersRepo";
import {
  listChatMembers,
  type ChatMember,
} from "../db/repositories/chatMembersRepo";
import {
  type Chat,
} from "../db/repositories/chatsRepo";
import {
  type Message,
} from "../db/repositories/messagesRepo";
import {
  pickNextSpeaker,
  type SpeakerCandidate,
} from "../chat/groupSpeaker";

/** Loads a chat's roster (`chat_members`) and the corresponding character
 *  cards, in roster order — characters that failed to load (deleted card)
 *  are skipped rather than breaking the whole load (plan §5). */
export async function loadMembers(chatId: string): Promise<{ members: ChatMember[]; memberCharacters: Character[] }> {
  const members = await listChatMembers(chatId);
  const loaded = await Promise.all(members.map((m) => getCharacter(m.characterId)));
  const memberCharacters = loaded.filter((c): c is Character => !!c);
  return { members, memberCharacters };
}

/** Resolves a speaker id (may be null/stale/not-yet-a-member) to a full
 *  `Character`, falling back to the chat's primary member, and — as a last
 *  resort, e.g. a cold `memberCharacters` cache — to a direct DB lookup
 *  (mirrors the pre-M10 "character couldn't load" degrade path). */
export async function resolveSpeaker(
  chat: Chat,
  memberCharacters: Character[],
  speakerId: string | null,
): Promise<Character | null> {
  const wantedId = speakerId ?? chat.characterId;
  const found = memberCharacters.find((c) => c.id === wantedId)
    ?? memberCharacters.find((c) => c.id === chat.characterId);
  if (found) return found;
  return getCharacter(wantedId);
}

/** Builds `{id, name, position}` candidates for `pickNextSpeaker` from the
 *  roster + loaded character cards (a member whose card failed to load gets
 *  an empty name — it simply can't be mention-matched by name). */
export function speakerCandidates(members: ChatMember[], memberCharacters: Character[]): SpeakerCandidate[] {
  const nameById = new Map(memberCharacters.map((c) => [c.id, c.name]));
  return members.map((m) => ({ id: m.characterId, name: nameById.get(m.characterId) ?? "", position: m.position }));
}

/** Chronological (oldest -> newest) authorship of assistant messages, with
 *  legacy/solo rows (`characterId === null`) attributed to the chat's
 *  primary member — the "recently spoken" signal for auto mode. */
export function recentSpeakerIds(chat: Chat, history: Message[]): string[] {
  return history.filter((m) => m.role === "assistant").map((m) => m.characterId ?? chat.characterId);
}

/** Picks who replies next: explicit selection in manual mode, or
 *  `pickNextSpeaker` (name mention / least-recently-spoken) in auto mode
 *  (plan §5). Always falls back to the chat's primary member. */
export function pickSpeakerId(
  chat: Chat,
  members: ChatMember[],
  memberCharacters: Character[],
  autoReply: boolean,
  selectedSpeakerId: string | null,
  lastUserText: string,
  history: Message[],
): string {
  if (!autoReply) return selectedSpeakerId ?? chat.characterId;
  const picked = pickNextSpeaker(
    speakerCandidates(members, memberCharacters),
    lastUserText,
    recentSpeakerIds(chat, history),
  );
  return picked ?? selectedSpeakerId ?? chat.characterId;
}

